INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-ukrainian-s2-q15','34295','ukrainian','2025','2','15','single_choice','Українським відповідником до іншомовного слова ремарка є','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"співзвучність","images":[]},{"marker":"Б","text":"послідовність","images":[]},{"marker":"В","text":"декорація","images":[]},{"marker":"Г","text":"завершення","images":[]},{"marker":"Д","text":"примітка","images":[]}]}]','e','Пояснення
