INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-mathematics-s2-q13','34407','mathematics','2025','2','13','single_choice','\(\frac{20^7\cdot 0\mathord{,}1^6}{4^5}=\)','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"\\(2\\mathord{,}5\\)","images":[]},{"marker":"Б","text":"\\(1\\mathord{,}25\\)","images":[]},{"marker":"В","text":"\\(8\\)","images":[]},{"marker":"Г","text":"\\(\\frac{1}{256}\\)","images":[]},{"marker":"Д","text":"\\(0\\mathord{,}000025\\)","images":[]}]}]','b','Пояснення
 ТЕМА: Алгебра і початки аналізу. Дійсні числа.
 Завдання скеровано на перевірку знання означення степеня з натуральним показником, його властивостей.
 \begin{gather*}
 \frac{20^7\cdot 0\mathord{,}1^6}{4^5}=\frac{20\cdot 20^6\cdot 0\mathord{,}1^6}{(2^2)^5}=\frac{20\cdot (20\cdot 0\mathord{,}1)^6}{2^{10}}=\\[6pt]
 =\frac{2\cdot 2\cdot 5\cdot 2^6}{2^{10}}=\frac{5}{2^2}=\frac 54=1\mathord{,}25.
 \end{gather*}
 Відповідь: Б.','[]','https://zno.osvita.ua/mathematics/672/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_mat-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','de0d0b6915c225b16dbf2f53e9a01f859b115f11036fc8a1e25361c717b72a04','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='mathematics' AND name='Дійсні числа та дії з ними')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('mathematics','Нерівності та їх системи','Рівняння, нерівності та їх системи',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-mathematics-s2-q14','34408','mathematics','2025','2','14','single_choice','Розв''яжіть нерівність \(\log_3(1-2x)\lt 2.\)','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"\\(\\left(0; \\frac 12\\right)\\)","images":[]},{"marker":"Б","text":"\\(\\left(-4; \\frac 12\\right)\\)","images":[]},{"marker":"В","text":"\\(\\left(\\frac 12; +\\infty\\right)\\)","images":[]},{"marker":"Г","text":"\\((-4; 0)\\)","images":[]},{"marker":"Д","text":"\\((-\\infty; -4)\\)","images":[]}]}]','b','Пояснення
 ТЕМА: Алгебра і початки аналізу Логарифмічні нерівності.
 Завдання скеровано на перевірку вміння розв’язувати логарифмічні нерівності, знання властивостей логарифмічної функції.
 \begin{gather*}
 \log_3(1-2x)\lt 2,\\[7pt]
 \log_3(1-2x)\lt \log_39.
 \end{gather*}
 Функція \(y=\log_3x\) є зростаючою, тому \(1-2x\lt 9.\) Логарифмічна функція має область визначення \(1-2x\gt 9.\)
 Отже, розв''язком нерівності буде розв''язок системи:
 \begin{gather*}
 \left\{
 \begin{array}{l}
 1-2x\lt 9,\\
 1-2x\gt 0,
 \end{array}
 \right.\ \ 
 \left\{
 \begin{array}{l}
 2x\gt -8,\\
 2x\lt 1,
 \end{array}
 \right.\ \ 
 \left\{
 \begin{array}{l}
 x\gt -4,\\
 x\lt \frac 12.
 \end{array}
 \right.
 \end{gather*}
 $$
 x\in \left(-4; \frac 12\right).
$$
 Відповідь: Б.','[]','https://zno.osvita.ua/mathematics/672/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_mat-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','dab4a1f40421a7850fb249d81e5b7d37000d357746447090842bf997a26b8798','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='mathematics' AND name='Нерівності та їх системи')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('mathematics','Чотирикутники й многокутники','Планіметрія',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-mathematics-s2-q15','34409','mathematics','2025','2','15','single_choice','На стороні \(AD\) прямокутника \(ABCD\) вибрано точку \(K\) так, що трикутник \(BKC\) є прямокутним (див. рисунок). Визначте периметр прямокутника \(ABCD\), якщо \(\angle ABK=30^\circ\), \(KC=6\sqrt{3}.\)','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"\\(24\\sqrt{3}+18\\)","images":[]},{"marker":"Б","text":"\\(24\\sqrt{3}+12\\)","images":[]},{"marker":"В","text":"\\(24+6\\sqrt{3}\\)","images":[]},{"marker":"Г","text":"\\(36\\)","images":[]},{"marker":"Д","text":"\\(36\\sqrt{3}\\)","images":[]}]}]','c','Пояснення
 ТЕМА: Геометрія. Планіметрія. Чотирикутники. Трикутники. 
 Завдання скеровано на перевірку вміння застосовувати властивості прямокутника та прямокутного трикутника.
 \(\angle ABC=90^\circ\), \(\angle ABK=30^\circ.\) Отже, \(\angle KBC=60^\circ.\)
 У \(\Delta BKC\ (\angle K=90^\circ)\ \angle C=30^\circ.\)
 У прямокутнику \(ABCD\ BC\ ||\ AD\), січна \(CK.\) \(\angle BCK=\angle CKD=30^\circ\) як внутрішні різносторонні.
 \(\Delta CKD\ (\angle D=90^\circ)\) 
 $$
 CD=\frac 12CK=\frac 12\cdot 6\sqrt{3}=3\sqrt{3}.
$$
 \(\Delta BKC\ (\angle K=90^\circ)\) 
 $$
 BC=\frac{CK}{\cos C}=\frac{6\sqrt{3}}{\frac{\sqrt{3}}{2}}=12.
$$
 $$
 P_{ABCD}=2(BC+CD)=2(12+3\sqrt{3})=24+6\sqrt{3}.
$$
 Відповідь: B.','["/question-assets/mathematics/34409-1.png"]','https://zno.osvita.ua/mathematics/672/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_mat-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','e61379f277a9f02d0ac6118aceadf13908ec86c0ffc3008b2529f948e98b1956','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='mathematics' AND name='Чотирикутники й многокутники')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('mathematics','Властивості та графіки функцій','Функції',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-mathematics-s2-q16','34410','mathematics','2025','2','16','matching','До кожного початку речення (1-3) доберіть його закінчення (А – Д) так, щоб утворилося правильне твердження.','[{"title":"Початок речення","options":[{"marker":"1","text":"Пряма \\(y=-2x\\)","images":[]},{"marker":"2","text":"Пряма \\(y=2x+2\\)","images":[]},{"marker":"3","text":"Пряма \\(y=-2x+4\\)","images":[]}]},{"title":"Закінчення речення","options":[{"marker":"А","text":"утворює гострий кут із додатним напрямком осі \\(x.\\)","images":[]},{"marker":"Б","text":"симетрична прямій \\(y=2x+4\\) відносно осі \\(y.\\)","images":[]},{"marker":"В","text":"є паралельною прямій \\(y=x.\\)","images":[]},{"marker":"Г","text":"проходить через початок координат.","images":[]},{"marker":"Д","text":"не перетинає жодну з осей координат.","images":[]}]}]','1d;2a;3b','Пояснення
 ТЕМА: Алгебра і початки аналізу. Функціональна залежність. 
 Завдання скеровано на перевірку вміння будувати графіки функцій, знання властивостей лінійної функцій.
 1.\(y=-2x\) проходить через початок координат.
 Отже, 1 – Г.
 2.\(y=2x+2\), \(k=2.\) Лінійна функція \(y=kx+b.\) При \(k\gt 0\) пряма утворює гострий кут із додатним напрямком осі \(x.\)
 Отже, 2 – А.
 3. \(y=-2x+4\) пряма симетрична прямій \(y=2x+4\) відносно осі \(y.\)
 Отже, 3 – Б.
 Відповідь: 1Г, 2А, 3Б.','[]','https://zno.osvita.ua/mathematics/672/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_mat-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','a1333a3930d71ad5e2d3fbfa52c95f0ba145260c1259e5356b8a1f67d454d436','1','official','matching',(SELECT id FROM topics WHERE subject_slug='mathematics' AND name='Властивості та графіки функцій')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('mathematics','Дійсні числа та дії з ними','Числа і вирази',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-mathematics-s2-q17','34411','mathematics','2025','2','17','matching','Узгодьте вираз (1-3) та проміжок (А – Д), якому належить його значення, де \(\mathbf{\varphi}=\frac{\sqrt{5}+1}{2}\) – відома математична величина, яку називають золотим числом.','[{"title":"Вираз","options":[{"marker":"1","text":"\\(\\mathbf{\\varphi}^0\\)","images":[]},{"marker":"2","text":"\\((\\sqrt{5}-1)\\cdot \\mathbf{\\varphi}\\)","images":[]},{"marker":"3","text":"\\(\\log_{\\frac 15}(2\\mathbf{\\varphi}-1)\\)","images":[]}]},{"title":"Проміжок","options":[{"marker":"А","text":"\\((-\\infty; -1]\\)","images":[]},{"marker":"Б","text":"\\((-1; 0]\\)","images":[]},{"marker":"В","text":"\\((0; 1]\\)","images":[]},{"marker":"Г","text":"\\((1; 2]\\)","images":[]},{"marker":"Д","text":"\\((2; +\\infty)\\)","images":[]}]}]','1c;2d;3b','Пояснення
 ТЕМА: Алгебра і початки аналізу. Дійсні числа та дії з ними.
 Завдання скеровано на перевірку вміння виконувати тотожні перетворення ірраціональних, логарифмічних та степеневих виразів.
 1. \(\mathbf{\varphi}^0=\left(\frac{\sqrt{5}+1}{2}\right)^0=1\in (0; 1].\)
 Отже, правильна відповідь – B.
 2. \((\sqrt{5}-1)\cdot \frac{\sqrt{5}+1}{2}=\frac{(\sqrt{5}-1)(\sqrt{5}+1)}{2}=\frac{5-1}{2}=2\in (1; 2].\) 
 Отже, правильна відповідь – Г.
 3. 
 \begin{gather*}
 \log_{\frac 15}(2\mathbf{\varphi}-1)=\log_{\frac 15}\left(2\cdot \frac{\sqrt{5}+1}{2}-1\right)=\\[6pt]
 =\log_{\frac 15}(\sqrt{5}+1-1)=\log_{\frac 15}\sqrt{5}=\log_{5^{-1}}5^{\frac 12}=\\[6pt]
 =-1\cdot \frac 12\cdot \log_55=-\frac 12\cdot 1=-0\mathord{,}5\in (-1; 0].
 \end{gather*}
 Отже, правильна відповідь – Б.
 При спрощенні виразу застосовували формули:
 \begin{gather*}
 \log_ab^n=n\cdot \log_ab,\\[6pt]
 \log_{a^k}b=\frac 1k\log_ab,\\[6pt]
 \log_aa=1.
 \end{gather*}
 Відповідь: 1В, 2Г, 3Б.','[]','https://zno.osvita.ua/mathematics/672/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_mat-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','05a6c4dbb1ee6044843d2ba25f30ffd7cee3a0044ff046458e41ce2d0d08e67f','1','official','matching',(SELECT id FROM topics WHERE subject_slug='mathematics' AND name='Дійсні числа та дії з ними')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('mathematics','Геометричні величини та вимірювання','Планіметрія',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-mathematics-s2-q18','34412','mathematics','2025','2','18','matching','На рисунку зображено квадрат \(ABCD.\) На стороні \(C\) вибрано точку \(K\) так, що \(KC=4\) см. Точка \(M\) – середина відрізка \(AK.\) Пряма, що проходить через точку \(M\) паралельно стороні \(BC\), перетинає сторони \(AB\) та \(CD\) в точках \(N\) і \(P\) відповідно, \(NM=6\) см. Узгодьте відрізок (1-3) та його довжину (А – Д).','[{"title":"Відрізок","options":[{"marker":"1","text":"\\(AB\\)","images":[]},{"marker":"2","text":"\\(MP\\)","images":[]},{"marker":"3","text":"\\(AK\\)","images":[]}]},{"title":"Довжина відрізка (см)","options":[{"marker":"А","text":"\\(10\\)","images":[]},{"marker":"Б","text":"\\(12\\)","images":[]},{"marker":"В","text":"\\(16\\)","images":[]},{"marker":"Г","text":"\\(20\\)","images":[]},{"marker":"Д","text":"\\(24\\)","images":[]}]}]','1c;2a;3d','Пояснення
 ТЕМА: Геометрія. Планіметрія. Чотирикутники. 
 Завдання скеровано на перевірку вміння застосовувати властивості трапеції та квадрата, розв’язування трикутників.
 \(NP\ ||\ BC\) 
 1 – В. Точка \(M\) – середина \(AK.\) За теоремою Фалеса: \(NM\ ||\ BC\) і \(AN=NB.\)
 У \(\Delta ABK\ NM\) – середня лінія. \(BK=2NM=12\) см.
 \(BC=BK+KC=12+4=16\) см. \(AB=BC=16\) см.
 2 – A.
 У трапеції \(AKCD\ MP\) – середня лінія.
 За властивістю середньої лінії:
 $$
 MP=\frac{KC+AD}{2}=\frac{4+16}{2}=10.
$$
 3 – Г. \(\Delta ABK\ (\angle B=90^\circ)\), \(AB=16\), \(BK=12.\) 
 За теоремою Піфагора:
 \begin{gather*}
 AK^2=AB^2+BK^2=16^2+12^2=256+144=400,\\[7pt]
 AK=20.
 \end{gather*}
 Відповідь: 1В, 2А, 3Г.','["/question-assets/mathematics/34412-1.png"]','https://zno.osvita.ua/mathematics/672/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_mat-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','6b4558611fb3123ec65d4a2aa86f8b76ce6ff088b2e5680f783c44865fd0f704','1','official','matching',(SELECT id FROM topics WHERE subject_slug='mathematics' AND name='Геометричні величини та вимірювання')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('mathematics','Властивості та графіки функцій','Функції',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-mathematics-s2-q19','34413','mathematics','2025','2','19','numeric','Функція \(f(x)\) є парною, а функція \(g(x)\) – непарною. Обчисліть значення виразу 
 $$
 \frac{4g(-x_0)+2f(x_0)}{5f(-x_0)},
$$
 якщо \(f(x_0)=1\), \(g(x_0)=-3.\)','[]','2.8','Пояснення
 ТЕМА: Алгебра і початки аналізу. Функціональна залежність. 
 Завдання скеровано на перевірку вміння застосовувати властивості числових функцій.
 Функція \(f(x)\) – парна, тому \(f(-x)=f(x).\)
 Функція \(g(x)\) – непарна, тому \(g(-x)=-g(x).\)
 \begin{gather*}
 \frac{4g(-x_0)+2f(x_0)}{5f(-x_0)}=\frac{-4g(x_0)+2f(x_0)}{5f(x_0)}=\\[6pt]
 =\frac{-4\cdot (-3)+2\cdot 1}{5\cdot 1}=\frac{12+2}{5}=\frac{14}{5}=2\mathord{,}8.
 \end{gather*}
 Відповідь: \(2\mathord{,}8.\)','[]','https://zno.osvita.ua/mathematics/672/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_mat-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','0c6bdb3a748f4c4f609e235ff911fbdd8937d3295164d08ddcb375efef2e8730','1','official','numeric',(SELECT id FROM topics WHERE subject_slug='mathematics' AND name='Властивості та графіки функцій')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('mathematics','Ймовірність випадкової події','Комбінаторика, ймовірність і статистика',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-mathematics-s2-q20','34414','mathematics','2025','2','20','numeric','На рисунку зображено схему салону пасажирського літака. У салоні \(n\) рядів, у кожному з яких розташовано по \(6\) крісел (по \(3\) крісла обабіч проходу ). Реєструючи пасажира, електронна система навмання вибирає для нього посадкове місце. Імовірність того, що першому зареєстрованому пасажиру дістанеться місце в перших трьох рядах, дорівнює \(\frac{1}{14}.\) Визначте \(n.\)','[]','42','Пояснення
 ТЕМА: Алгебра і початки аналізу. Ймовірність випадкової події. 
 Завдання скеровано на перевірку вміння обчислювати ймовірність випадкових подій, знання класичного означення ймовірної події. 
 У салоні \(n\) рядів, у кожному з яких розташовано \(6\) крісел. Отже, всього в салоні \(6n\) місць.
 У перших трьох рядах розташовано \(18\) місць.
 Імовірність того, що пасажиру дістанеться таке місце,
 $$
 P=\frac{18}{6n}=\frac 3n.
$$
 За умовою ця імовірність дорівнює \(\frac{1}{14}.\)
 \begin{gather*}
 \frac 3n=\frac{1}{14},\\[6pt]
 n=42.
 \end{gather*}
 Відповідь: \(42.\)','["/question-assets/mathematics/34414-1.jpeg"]','https://zno.osvita.ua/mathematics/672/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_mat-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','8f48343e9fc2830a0c6c6aee687ba11cfcaa1c2bf19bf52f466e01c4812bee62','1','official','numeric',(SELECT id FROM topics WHERE subject_slug='mathematics' AND name='Ймовірність випадкової події')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('mathematics','Многогранники','Стереометрія',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-mathematics-s2-q21','34415','mathematics','2025','2','21','numeric','Твірна конуса й бічне ребро правильної трикутної піраміди дорівнюють по \(25\) см. Апофема піраміди дорівнює радіусу основи конуса. Обчисліть площу (см\(^2\)) бічної поверхні піраміди, якщо площа бічної поверхні конуса дорівнює \(500\mathbf{\pi}\) см\(^2.\)','[]','900','Пояснення
 ТЕМА: Геометрія. Стереометрія. Многогранники, тіла обертання.
 Завдання скеровано на перевірку знань властивостей піраміди та конуса, вміння розв’язувати задачі на обчислення площ поверхонь геометричних тіл.
 Твірна консуса \(AB\) й бічне ребро \(CF\) дорівнюють по \(25\) см. Апофема \(FK=OB.\)
 Площа бічної поверхні конуса
 $$
 S_\text{б}=\mathbf{\pi}RL,
$$
 де \(R=OB\), \(L=AB.\)
 \begin{gather*}
 \mathbf{\pi}\cdot OB\cdot 25=500\mathbf{\pi},\\[7pt]
 OB=20\ \textit{см}.
 \end{gather*}
 У піраміді \(CF=FD=FE=25.\) \(\Delta FKD\ (\angle K=90^\circ).\) За теоремою Піфагора:
 \begin{gather*}
 FD^2=FK^2+KD^2,\\[7pt]
 KD^2=25^2-20^2=625-400=225,\\[7pt]
 KD=15\ \textit{см},\\[7pt]
 DE=2KD=30\ \textit{см}.
 \end{gather*}
 Площа бічної поверхні піраміди
 $$
 S_\text{б}=\frac 12P_\text{осн}\cdot m,
$$
 де \(P_\text{осн}=3\cdot ED=90\ \textit{см}\), \(m=FK=20\ \textit{см}.\)
 $$
 S_\text{б}=\frac 12\cdot 90\cdot 20=900\ \textit{см}^2.
$$ 
 Відповідь: \(900.\)','[]','https://zno.osvita.ua/mathematics/672/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_mat-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','1d4983a159165d0c5b257952035cedad98a5921c97a54c05bd0b9fec189e7d0a','1','official','numeric',(SELECT id FROM topics WHERE subject_slug='mathematics' AND name='Многогранники')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('mathematics','Раціональні рівняння','Рівняння, нерівності та їх системи',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-mathematics-s2-q22','34416','mathematics','2025','2','22','numeric','Визначте значення \(a\), за якого система рівнянь 
 $$
 \left\{
 \begin{array}{l}
 y+(x-1)^2=5a, \\
 x^2-2x+y^2+8y=47.
 \end{array}
 \right.
$$
 має єдиний розв''язок.','[]','-2.4','Пояснення
 ТЕМА: Алгебра і початки аналізу. Розв’язування раціональних рівнянь.
 Завдання скеровано на перевірку вміння розв’язувати раціональні рівняння, та їх системи з параметрами.
 \begin{gather*}
 \left\{
 \begin{array}{l}
 y+(x-1)^2=5a,\\
 x^2-2x+y^2+8y=47,
 \end{array}
 \right.\ \ 
 \left\{
 \begin{array}{l}
 (x-1)^2+y=5a,\\
 (x^2-2x+1)+(y^2+8y+16)=64,
 \end{array}
 \right.\\[7pt] 
 \left\{
 \begin{array}{l}
 y=-(x-1)^2+5a,\\
 (x-1)^2+(y+4)^2=64.
 \end{array}
 \right.
 \end{gather*}
 Розв''яжемо систему графічним способом.
 \((x-1)^2+(y+4)^2=64\) – рівняння кола з центром \((1; -4)\) і радіусом \(8.\)
 \(y=-(x-1)^2+5a\) – квадратична функція з вершиною в точці \((1; 5a)\) з вітками вниз.
 Для того, щоб система мала єдиний розв''язок, треба, щоб графіки мали одну спільну точку.
 Отже,
 \begin{gather*}
 5a=-12,\\[7pt]
 a=-12:5=-2\mathord{,}4.
 \end{gather*}
 Відповідь: \(-2\mathord{,}4.\)','[]','https://zno.osvita.ua/mathematics/672/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_mat-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','034110f30368ea492a3ba7b4a2c9afe3f89dfa3c35006b5671bd9c08692bde83','1','official','numeric',(SELECT id FROM topics WHERE subject_slug='mathematics' AND name='Раціональні рівняння')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
