INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-german-s1-q5','34487','german','2025','1','5','single_choice','Es ist eine der populärsten Sehenswürdigkeiten in Deutschland: der Kölner Dom. Zum ersten Mal seit mehr als zehn Jahren sind seine zwei Türme wieder komplett zu sehen. Wegen Restaurierungsarbeiten hat am Nordturm der Kirche in einer Höhe von 105 Metern ein 30 Meter hohes Aluminium-Gerüst gehangen. Jetzt ist es demontiert. Grund für die Restaurierung waren Schäden nach einem schweren Sturm im Jahr 1984. Die komplette Kirche im gotischen Stil kann man aber nicht sehen, denn der Dom wird permanent restauriert. Trotzdem ist wegen des aktuellen Blicks auf die Türme jetzt die perfekte Zeit für einen Besuch in Köln.','[{"title":"Варіанти відповіді","options":[{"marker":"A","text":"Herzlich Willkommen in Köln!","images":[]},{"marker":"B","text":"Augsburg statt Regensburg: Ein Tipp für Touristen","images":[]},{"marker":"C","text":"Den Ort Dorf gibt es wirklich","images":[]},{"marker":"D","text":"Viele historische Objekte in Köln brauchen Restaurierung","images":[]},{"marker":"E","text":"Ein wahres Beispiel der Liebe zu seinem Nächsten","images":[]},{"marker":"F","text":"Warum bevorzugen Touristen Augsburg statt Regensburg?","images":[]},{"marker":"G","text":"Kleine Stadt, die viel anbieten kann","images":[]},{"marker":"H","text":"Ein kleiner Schweizer Ort ist berühmt geworden","images":[]}]}]','a','','[]','https://zno.osvita.ua/german/675/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_ger-1.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','ea61ca5dd88e35f4c88de91d93d68731386b56306e5f9a25a5ffd62924671203','1','official','language_matching',(SELECT id FROM topics WHERE subject_slug='german' AND name='Hauptaussage und Zweck')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
