INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-history-s1-q15','34325','history','2025','1','15','single_choice','Який процес доби радянської модернізації України схарактеризовано в уривку документа: «...ЦК ВКП(б) визнає недоцільним і шкідливим подальше існування особливих національних шкіл, особливих національних відділів та класів при звичайних радянських школах і постановляє реорганізувати особливі національні німецькі, польські, чеські, шведські й інші школи й технікуми в радянські школи звичайного типу...»?','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"початок «червоного терору»","images":[]},{"marker":"Б","text":"згортання політики коренізації","images":[]},{"marker":"В","text":"розвиток вищої освіти","images":[]},{"marker":"Г","text":"боротьба з неписьменністю","images":[]}]}]','b','Пояснення
 ТЕМА: Утвердження більшовицького тоталітарного режиму в Україні.
В уривку джерела йдеться про згортання радянською владою політики коренізації, яка передбачала, зокрема, функціонування в районах компактного проживання національних меншин шкіл із німецькою, болгарською, єврейською, польською та іншими мовами навчання.
Всеукраїнський Центральний Виконавчий Комітет та Рада народних комісарів Української Соціалістичної Радянської Республіки (УСРР) 1923 року ухвалили декрет «Про заходи рівноправності мов і про допомогу розвиткові української мови». То був один з етапів політики коренізації, яка в радянській Україні набула форми українізації.
Радянська коренізація була насамперед засобом утвердження радянської влади. Однак, коли стало очевидним те, що на місцях ця політика стимулювала зростання національної самосвідомості, влада поступово почала згортати її й карати причетних до її поступу.
Правильна відповідь – Б.','[]','https://zno.osvita.ua/ukraine-history/669/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_his-1.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','de6c489d7ed4ed6f4ccfd28e97f3966577b287b3e35eda981bad2af439ca6b8e','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='history' AND name='Утвердження більшовицького тоталітарного режиму в Україні')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
