INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('history','Україна в період загострення кризи радянської системи','Україна після 1945 року',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-history-s1-q18','34328','history','2025','1','18','single_choice','Яке явище радянської дійсності 1980-х років відображено карикатуристом?','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"занепад культури","images":[]},{"marker":"Б","text":"фінансові проблеми","images":[]},{"marker":"В","text":"хронічний дефіцит","images":[]},{"marker":"Г","text":"зростання безробіття","images":[]}]}]','c','Пояснення
 ТЕМА: Україна в період загострення кризи радянської системи.
Карикатура візуалізує хронічний дефіцит – економічне і соціальне явище, притаманне радянській плановій економіці, особливо в період загострення кризи радянської системи.
В СРСР існувала диспропорція між пропозицією товарів для населення і грошовими доходами громадян. Нестача якісних товарів і послуг, відсутність широкого вибору породжувала на них підвищений попит. Ближче до 1980-х у повсякдення входять такі поняття як дефіцит і черга.
Причини дефіциту в період застою були комплексними: мілітаризація економіки, недорозвиненість легкої та харчової промисловості, відставання в розробленні нових технологій тощо.
Правильна відповідь – В.','["/question-assets/history/34328-1.png"]','https://zno.osvita.ua/ukraine-history/669/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_his-1.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','b16ec86eca67616b160166aef99597040b71356294d5f691bb3404ed36375d6d','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='history' AND name='Україна в період загострення кризи радянської системи')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
