INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-history-s1-q19','34329','history','2025','1','19','single_choice','Прочитайте уривок документа: «Уранці 19 серпня командувач сухопутними військами СРСР генерал В. Варенников, прибувши з групою військових до кабінету Голови Верховної Ради УРСР, в ультимативній формі йому заявив: "Влада перейшла до ДКНС, який врятує країну. Рекомендую Вам зайняти правильну позицію. Змінити свій особистий курс і курс Верховної Ради...»
Наслідком описаної в документі події стало','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"ухвалення Верховною Радою УРСР Декларації про державний суверенітет України.","images":[]},{"marker":"Б","text":"проведення перших альтернативних виборів до Верховної Ради УРСР.","images":[]},{"marker":"В","text":"ухвалення Конституції України.","images":[]},{"marker":"Г","text":"ухвалення Верховною Радою УРСР Акта проголошення незалежності України.","images":[]}]}]','d','Пояснення
 ТЕМА: Відновлення незалежності України
Політичні сили, які прагнули зупинити демократичні перетворення й зберегти СРСР у старому форматі, 19 серпня 1991 року здійснили спробу державного заколоту. Самопроголошений «Державний комітет із надзвичайного стану» (російською – ГКЧП) намагався усунути від влади Президента СРСР Михайла Горбачова. Від тодішнього голови українського парламенту Леоніда Кравчука путчисти вимагали підтримати їх й оголосити в Україні надзвичайний стан.
Масові акції громадянської непокори, мітинги та страйки, відмова підкорятися указам ДКНС зупинили путч. Україна використала свій шанс: скликана надзвичайна сесія Верховної Ради України 24 серпня 1991 року ухвалила Акт проголошення незалежності України.
Правильна відповідь – Г.','[]','https://zno.osvita.ua/ukraine-history/669/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_his-1.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','9de5d5306b40bd4ad9a55d5c148a32771fe4db4422992dd264f11b24b2ec5b24','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='history' AND name='Відновлення незалежності України')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
