INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-history-s1-q20','34330','history','2025','1','20','single_choice','Що спричинило події, яким приурочено плакат?','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"спроба влади придушити Євромайдан","images":[]},{"marker":"Б","text":"окупація Росією Кримського півострова","images":[]},{"marker":"В","text":"достроковий розпуск Верховної Ради України","images":[]},{"marker":"Г","text":"фальсифікація владою президентських виборів","images":[]}]}]','a','Пояснення
 ТЕМА: Творення нової України.
Плакат присвячено подіям Революції Гідності.
Відмова тодішнього президента Віктора Януковича підписати Угоду про асоціацію з Євросоюзом на саміті «Східного партнерства» у Вільнюсі спричинила в Києві та регіонах мирні протести, які розпочалися 21 листопада 2013 року. Євроінтеграційні гасла дали акції назву Євромайдан.
Після силового розгону 30 листопада Євромайдан став рушієм кардинальних змін у країні, запустив процес повного оновлення державної системи й отримав назву «Революція Гідності».
Майдан радикалізувався: зʼявилися барикади, полетіли коктейлі Молотова, запалали шини. Під час протистояння із силовиками загинуло 107 учасників й учасниць акції протесту – Героїв України, названих Небесною Сотнею.
Революція Гідності сприяла подальшому формуванню громадянського суспільства. З Майдану навесні 2014 року добровольці вирушили на український Схід, щоб захистити його від російської агресії. З лютого 2022 року після широкомасштабного вторгнення багато учасників й учасниць Революції Гідності стали на захист України від ворожої навали.
Правильна відповідь – А.','["/question-assets/history/34330-1.png"]','https://zno.osvita.ua/ukraine-history/669/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_his-1.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','a61dbf5d04ca8ab673701c1e020f239d332fb3fad201ed531a8860892c24a473','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='history' AND name='Творення нової України')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('history','Міжтематичні завдання з історії України','Узагальнення',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-history-s1-q21','34331','history','2025','1','21','matching','На фото зображено реверси (зворотні сторони) пам''ятних монет (1-4), присвячених відомим архітектурним пам''яткам України.
З''ясуйте, історико-архітектурною спадщиною якого з регіонів (А – Д) є кожна з цих пам''яток.','[{"title":"Варіанти відповіді","options":[{"marker":"1","text":"","images":["/question-assets/history/34331-o1-1.png"]},{"marker":"2","text":"","images":["/question-assets/history/34331-o2-1.png"]},{"marker":"3","text":"","images":["/question-assets/history/34331-o3-1.png"]},{"marker":"4","text":"","images":["/question-assets/history/34331-o4-1.png"]}]},{"title":"Варіанти відповіді","options":[{"marker":"А","text":"Волинь","images":[]},{"marker":"Б","text":"Галичина","images":[]},{"marker":"В","text":"Хотинщина","images":[]},{"marker":"Г","text":"Поділля","images":[]},{"marker":"Д","text":"Крим","images":[]}]}]','1c;2b;3e;4d','Пояснення
 ТЕМА: Руські удільні князівства в складі іноземних держав у другій половині XIV – першій половині XVI ст. Кримське ханство. Українські землі в складі Речі Посполитої в першій половині XVII ст.
1 – В Хотинська фортеця (Хотинщина)
2 – Б замок у с. Підгірці (Галичина) 
3 – Д Генуезька фортеця в м. Судак (Крим)
4 – Г Камʼянець-Подільська фортеця (Поділля)
Правильна відповідь: 1 – В, 2 – Б, 3 – Д, 4 – Г.','[]','https://zno.osvita.ua/ukraine-history/669/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_his-1.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','b9f1a7194e71029b24636bb28a57efec2ebb8df4426e924e92eb51f64d0a340c','1','official','matching',(SELECT id FROM topics WHERE subject_slug='history' AND name='Міжтематичні завдання з історії України')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
