INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-history-s1-q22','34332','history','2025','1','22','matching','Узгодьте подію (1-4) з роком (А – Д), коли вона відбулася.','[{"title":"Варіанти відповіді","options":[{"marker":"1","text":"проголошення курсу на індустріалізацію","images":[]},{"marker":"2","text":"входження УСРР до складу СРСР","images":[]},{"marker":"3","text":"утворення Української автокефальної православної церкви","images":[]},{"marker":"4","text":"початок насильницької колективізації","images":[]}]},{"title":"Варіанти відповіді","options":[{"marker":"А","text":"1921 р.","images":[]},{"marker":"Б","text":"1922 р.","images":[]},{"marker":"В","text":"1923 р.","images":[]},{"marker":"Г","text":"1925 р.","images":[]},{"marker":"Д","text":"1929 р.","images":[]}]}]','1d;2b;3a;4e','Пояснення
 ТЕМА: Встановлення комуністичного тоталітарного режиму в Україні. Утвердження більшовицького тоталітарного режиму в Україні
1 – Г XIV з''їзд ВКП(б) в грудні 1925 року проголосив курс на індустріалізацію – систему заходів, спрямованих на прискорений розвиток важкої промисловості з метою технічного переоснащення економіки й зміцнення оборонного потенціалу держави.
2 – Б І з’їзд рад СРСР 30 грудня 1922 року затвердив декларацію про утворення Союзу Радянських Соціалістичних республік. Засновницями СРСР були Російська СФРР, Білоруська СРР, Українська Соціалістична Радянська Республіка (УСРР), Закавказька СФРР у складі Азербайджану, Вірменії, Грузії.
3 – А Всеукраїнський православний церковний собор у жовтні 1921 року в Києві проголосив створення Української автокефальної православної церкви. Учасники Собору висвятили першого предстоятеля УАПЦ митрополита Василя (Липківського).
4 – Д 7 листопада 1929 року газета «Правда» опублікувала статтю Сталіна «Рік великого перелому (До 12-ої річниці Жовтня)». Відповідно до її установок пленум ЦК ВКП(б) визнав недостатніми темпи усуспільнення селянських господарств і проголосив перехід до суцільної колективізації сільського господарства.
Правильна відповідь: 1 – Г, 2 – Б, 3 – А, 4 – Д.','[]','https://zno.osvita.ua/ukraine-history/669/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_his-1.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','05b7a5f1a3d4358c7cd26c0b5548a55c77b42330b9dd0421f11bd7dc70a22ef0','1','official','matching',(SELECT id FROM topics WHERE subject_slug='history' AND name='Міжтематичні завдання з історії України')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('history','Україна в роки Другої світової війни','Міжвоєнна доба і Друга світова війна',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-history-s1-q23','34333','history','2025','1','23','matching','Поєднайте термін (1-4) з його визначенням (А – Д).','[{"title":"Варіанти відповіді","options":[{"marker":"1","text":"«депортація»","images":[]},{"marker":"2","text":"«мобілізація»","images":[]},{"marker":"3","text":"«евакуація»","images":[]},{"marker":"4","text":"«еміграція»","images":[]}]},{"title":"Варіанти відповіді","options":[{"marker":"А","text":"вивезення населення, особливо спеціалістів, а також матеріальних цінностей з місцевостей, що перебувають під загрозою стихійного лиха, нападу або загарбання ворогом","images":[]},{"marker":"Б","text":"призов військовозобов''язаних на службу в діючу армію у зв''язку із запровадженням воєнного стану","images":[]},{"marker":"В","text":"вимушене або добровільне переселення частини населення з батьківщини до іншої країни на певний час або на постійне мешкання","images":[]},{"marker":"Г","text":"примусове, насильницьке переселення людей за межі місць їхнього постійного проживання","images":[]},{"marker":"Д","text":"примусове безоплатне або оплачуване відчуження майна органами державної влади","images":[]}]}]','1d;2b;3a;4c','Пояснення
 ТЕМА: Україна в роки Другої світової війни.
1 – Г Депортація – примусове, насильницьке переселення людей за межі місць їхнього постійного проживання.
2 – Б Мобілізація – призов військовозобов''язаних на службу в армію у зв''язку із запровадженням воєнного стану.
3 – А Евакуація – вивезення населення, особливо фахівців, а також матеріальних цінностей із місцевостей, що перебувають під загрозою стихійного лиха, нападу або загарбання ворогом.
4 – В («еміграція»): вимушене або добровільне переселення частини населення з батьківщини до іншої країни на певний час або на постійне мешкання.
Правильна відповідь: 1 – Г, 2 – Б, 3 – А, 4 – В.','[]','https://zno.osvita.ua/ukraine-history/669/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_his-1.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','d4171d1663800e42f158bb4030012649434d12c0f3fb2708a9d1e38f54bb7cad','1','official','matching',(SELECT id FROM topics WHERE subject_slug='history' AND name='Україна в роки Другої світової війни')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('history','Міжтематичні завдання з історії України','Узагальнення',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-history-s1-q24','34334','history','2025','1','24','matching','Узгодьте ім''я видатної діячки мистецтва (1-4) з уривком спогадів про неї (А – Д).','[{"title":"Варіанти відповіді","options":[{"marker":"1","text":"Катерина Білокур","images":[]},{"marker":"2","text":"Алла Горська","images":[]},{"marker":"3","text":"Ліна Костенко","images":[]},{"marker":"4","text":"Олена Теліга","images":[]}]},{"title":"Варіанти відповіді","options":[{"marker":"А","text":"«Її ім''я стало відомим на рідній землі лише після того, як здійснилась її заповітна мрія, за яку віддала життя, – Україна стала незалежною державою. За радянських часів її ім''я замовчувалося, бо було позначене, як імена тисяч інших борців за незалежну Українську державу, тавром \"українського буржуазного націоналізму\", віднесено до \"ворогів народу\"...»","images":[]},{"marker":"Б","text":"«Вона творила монументальні полотна, а радянська влада їх нищила, як \"ідейно ворожі\". За нею постійно стежили агенти КДБ, а вона кепкувала зі \"шпиків\" і вітала всіх звільнених із таборів політв''язнів. ...українська художниця-шістдесятниця, товаришка Василя Стуса, Євгена Сверстюка, родини Світличних, В''ячеслава Чорновола. Вона не визнавала обмежень у творчості, свободі слова й думки...»","images":[]},{"marker":"В","text":"«1954 року в Парижі на міжнародній виставці демонструють її картини \"Цар-колос\", \"Берізка\" й \"Колгоспне поле\", які високо оцінив Пабло Пікассо. Кажуть, що він довго стояв біля полотен, мов загіпнотизований, а потім назвав її геніальною і порівняв із Серафін Луїз із міста Санлі, відомою художницею, що вславилася в наївному мистецтві й також малювала квіти. І додав: \"Якби в нас була такого рівня художниця, ми змусили б світ заговорити про неї...»","images":[]},{"marker":"Г","text":"«У 70-ті роки [вона] потрапила до \"чорного списку\", складеного особисто секретарем ЦК КПУ з ідеології Маланчуком. Лише після його відходу в 1977 році виходить в світ збірка віршів \"Над берегами вічної ріки\", а через два роки – спеціальною постановою Президії СПУ – історичний роман у віршах \"Маруся Чурай\", що пролежав без руху 6 років...»","images":[]},{"marker":"Д","text":"«Для України ж вона є особливо знаковою – поліська селянка, яка досягла світового визнання й мистецьких вершин, створивши свою візуальну мову. Її чарівні фантастичні звірі, птахи й квіти радують око не тільки на картинах, створених геніальною художницею. Вони легко переселяються на сучасні автомобілі, стають елементами модного одягу й дизайну...»","images":[]}]}]','1c;2b;3d;4a','Пояснення
 ТЕМА: Україна в роки Другої світової війни. Україна в умовах десталінізації.
1 – В Представниця народного декоративного живопису Катерина Білокур найбільше малювала квіти. Її квіти реальні й водночас казкові. Три картини Білокур – «Цар-Колос», «Берізка», «Колгоспне поле» – були частиною експозиції радянського мистецтва на Міжнародній виставці в Парижі 1954 року.
2 – Б Художниця Алла Горська – представниця руху шістдесятників, одна з організаторок Клубу творчої молоді «Сучасник», правозахисниця і дисидентка. Разом з Опанасом Заливахою, Людмилою Семикіною, Галиною Севрук і Галиною Зубченко створила 1964 року в Червоному корпусі Київського університету вітраж «Шевченко. Мати», який напередодні відкриття за вказівкою партійного керівництва знищила адміністрація університету. Скликана після цього комісія кваліфікувала його як «ідейно ворожий, глибоко чужий принципам соціалістичного реалізму».
3 – Г Ліна Костенко – поетка, публіцистка, представниця руху шістдесятників. Відкрито виступала на захист українських дисидентів, чим викликала табу на видання своїх творів. Після її відкритого листа на захист Чорновола в газету «Літературна Україна» ім’я Ліни Василівни не згадували й у пресі. Шістнадцять років поетка працюватиме «в стіл», проявляючи твердість і безкомпромісність. До широкого читацького кола поезія Костенко змогла повернутися лише 1977 року збіркою віршів «Над берегами вічної ріки». А 1979-го було опубліковано надзвичайної художньої сили історико-філософський соціально-психологічний роман у віршах «Маруся Чурай».
4 – А Поетка, член ОУН Олена Теліга після початку німецько-радянської війни, у жовтні 1941 року прибула в окупований Київ. Теліга очолила Спілку українських письменників, редагувала щотижневий літературно-мистецький додаток до газети «Українське слово» – «Літаври». З початком масових арештів серед українських націоналістів відмовилася виконати наказ Проводу українських націоналістів про виїзд із Києва. 9 лютого 1942 року була заарештована гестапо. Страчена й похована в Бабиному Яру.
За радянських часів імʼя Олени Теліги замовчували в Україні. Тільки з настанням незалежності його повернули нам.
Правильна відповідь: 1 – В, 2 – Б, 3 – Г, 4 – А.','[]','https://zno.osvita.ua/ukraine-history/669/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_his-1.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','a757df2a8f9034e86051497964c354bf106a8c57335b623daf48c8c202e03ef2','1','official','matching',(SELECT id FROM topics WHERE subject_slug='history' AND name='Міжтематичні завдання з історії України')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('history','Міжтематичні завдання з історії України','Узагальнення',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-history-s1-q25','34335','history','2025','1','25','ordering','Розташуйте поняття відповідно до перебігу соціально-економічних процесів, яким вони відповідають.','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"«відруб»","images":[]},{"marker":"Б","text":"«вотчина»","images":[]},{"marker":"В","text":"«полюддя»","images":[]},{"marker":"Г","text":"«фільварок»","images":[]}]}]','1c;2b;3d;4a','Пояснення
 ТЕМА: Русь-Україна (Київська держава). Руські удільні князівства в складі іноземних держав у другій половині XIV – першій половині XVI ст. Українські землі в складі Речі Посполитої в другій половині XVI ст. Українські землі в складі Російської імперії в 1900–1914 рр.
Послідовність понять відповідно до перебігу соціально-економічних процесів:
В Полюддя – процес збирання князем із дружиною данини у формі натурального оброку з підлеглого населення в Русі (Київській державі). Після древлянського повстання в Х ст. княгиня Ольга регламентувала обсяг данини й визначила пункти для її збирання, відмовившись від полюддя.
Б Вотчина – спадкова земельна власність князів, бояр та інших членів панівної верхівки в Русі-Україні (Київській державі) й середньовічній Україні. Власник вотчини мав право передати її в спадок, продати, обміняти, поділити тощо. Перші вотчини виникають з другої половини XI ст. До того земля перебувала в колективній власності панівної верстви.
Г Фільварок – форма господарювання, багатогалузеве господарство, зорієнтоване на виробництво сільськогосподарської продукції для продажу. У фільварках використовували працю кріпаків, а пізніше – найману працю. У XV ст. фільварки вперше зʼявилися на українських землях, які перебували в складі Королівства Польського. Тут сільське господарство поступово переорієнтовували на потреби європейського ринку. На українських землях, які були в складі Великого князівства Литовського, фільваркова система господарювання набула поширення із середини XVI ст.
А Відруб – земельний наділ, який мав право отримати селянин у приватну власність за умовами аграрної реформи, розпочатої 1906 року Петром Столипіним.
Правильна відповідь: В, Б, Г, А.','[]','https://zno.osvita.ua/ukraine-history/669/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_his-1.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','071d60ffdd839777e07e459087da6b6f8453deeb8d371de7e829b11c2154d578','1','official','ordering',(SELECT id FROM topics WHERE subject_slug='history' AND name='Міжтематичні завдання з історії України')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('history','Міжтематичні завдання з історії України','Узагальнення',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-history-s1-q26','34336','history','2025','1','26','ordering','Установіть послідовність перебування на посаді гетьманів / кошових отаманів.','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"Іван Сірко","images":[]},{"marker":"Б","text":"Дмитро (Байда) Вишневецький","images":[]},{"marker":"В","text":"Петро Калнишевський","images":[]},{"marker":"Г","text":"Петро Конашевич-Сагайдачний","images":[]}]}]','1b;2d;3a;4c','Пояснення
 ТЕМА: Українські землі у складі Речі Посполитої в другій половині XVI ст. Українські землі у складі Речі Посполитої в першій половині XVII ст. Козацька Україна наприкінці 50-80-х рр. XVII ст. Українські землі в другій половині XVIII ст.
Послідовність перебування на посаді гетьманів / кошових отаманів:
Б Дмитро (Байда) Вишневецький – козацький ватажок, один із перших козацьких гетьманів України, який 1556 року збудував на Малій Хортиці першу Запорозьку Січ.
Г Петро Конашевич-Сагайдачний – гетьман реєстрового козацтва, кошовий отаман Запорозької Січі, один із засновників козацького флоту, організатор успішних морських походів запорозьких козаків проти Кримського ханства й Османської імперії «доби героїчних походів» (перші два десятиліття XVII ст.)
А Іван Сірко – легендарний кошовий отаман Запорозької Січі й усього Війська Запорозького Низового доби Руїни (кінець 50–80-х рр. XVII ст.)
В Петро Калнишевський – останній кошовий отаман Запорозької (Нової) Січі, зруйнованої 1775 року.
Правильна відповідь: Б, Г, А, В.','[]','https://zno.osvita.ua/ukraine-history/669/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_his-1.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','3869f525a49dd2b6b7a553a8f13198a55bef08ac8c0471fa0f6c0dc50e70a48d','1','official','ordering',(SELECT id FROM topics WHERE subject_slug='history' AND name='Міжтематичні завдання з історії України')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
