INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-history-s1-q27','34337','history','2025','1','27','ordering','Установіть послідовність подій, зафіксованих на фото.','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"","images":["/question-assets/history/34337-o1-1.png"]},{"marker":"Б","text":"","images":["/question-assets/history/34337-o2-1.png"]},{"marker":"В","text":"","images":["/question-assets/history/34337-o3-1.png"]},{"marker":"Г","text":"","images":["/question-assets/history/34337-o4-1.png"]}]}]','1b;2d;3c;4a','Пояснення
 ТЕМА: Початок Української революції. Утвердження більшовицького тоталітарного режиму в Україні. Західноукраїнські землі в міжвоєнний період. Україна в роки Другої світової війни.
Послідовність подій, зафіксованих на фото:
Б На фото зафіксовано солдатів Волинського полку – активних учасників революційних подій у Петрограді 1917 року (Лютнева революція), унаслідок яких було повалено монархію. 2 (15) березня 1917 року імператор Микола II зрікся престолу. Ця подія стала відправною точкою розгортання Української революції та становлення України – спочатку як автономії, а потім як незалежної держави.
Г Фото є пропагандистським складником політики суцільної колективізації та розкуркулення. Гасло суцільної колективізації проголосив листопадовий 1929 року пленум ЦК ВКП(б). За пропозицією Й. Сталіна 1930 року було визначено стратегічне завдання ліквідувати куркульство як клас. Під розкуркулювання попадали не тільки заможні селяни, що використовували найману працю (куркулі), але й ті, хто не погоджувався йти в колгосп.
В На фото зафіксовано фрагмент історії Карпатської України. У жовтні 1938 року було проголошено її автономію в складі Чехо-Словаччини, а 15 березня 1939 року Сойм Карпатської України оголосив про державну незалежність.
А На фото радянські солдати готуються до форсування Дніпра. Битва за Київ була одним із ключових епізодів Битви за Дніпро, яка тривала з кінця літа до кінця грудня 1943 року. Радянські війська, форсуючи Дніпро, зазнали колосальних утрат, але здолали ворожий опір.
Правильна відповідь: Б, Г, В, А.','[]','https://zno.osvita.ua/ukraine-history/669/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_his-1.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','91f1830146da75d8f0e8ff85643c1c42b30e052581dfa725acd0da650d1abf63','1','official','ordering',(SELECT id FROM topics WHERE subject_slug='history' AND name='Міжтематичні завдання з історії України')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('history','Українські землі у складі Російської імперії наприкінці XVIII – у першій половині XIX ст.','Українські землі у складі імперій',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-history-s1-q28','34338','history','2025','1','28','multiple_choice','Які губернії Російської імперії створено у ХІХ ст. на землях колишньої Лівобережної Гетьманщини та Слобожанщини?','[{"title":"Варіанти відповіді","options":[{"marker":"1","text":"Чернігівську","images":[]},{"marker":"2","text":"Миколаївську","images":[]},{"marker":"3","text":"Харківську","images":[]},{"marker":"4","text":"Київську","images":[]},{"marker":"5","text":"Полтавську","images":[]},{"marker":"6","text":"Таврійську","images":[]},{"marker":"7","text":"Катеринославську","images":[]}]}]','1;3;5','Пояснення
 ТЕМА: Українські землі в складі Російської імперії наприкінці XVIII – у першій половині XIX ст.
На землях колишньої Лівобережної Гетьманщини та Слобожанщини на початку ХІХ століття (у 1802 році) було остаточно сформовано три основні губернії.
1 – Чернігівська губернія: охоплювала північну частину Лівобережжя.
5 – Полтавська губернія: охоплювала південну частину Лівобережжя.
3 – Харківська губернія: (тривалий час мала назву Слобідсько-Українська, з 1835 року — Харківська).
Правильна відповідь: 1, 3, 5','[]','https://zno.osvita.ua/ukraine-history/669/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_his-1.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','f408a9d828128b691c9a9eb104d179276a32ef8a71c5a5dec54c28bd83e2bfae','1','official','multiple_choice',(SELECT id FROM topics WHERE subject_slug='history' AND name='Українські землі у складі Російської імперії наприкінці XVIII – у першій половині XIX ст.')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('history','Початок Української революції','Війна та Українська революція',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-history-s1-q29','34339','history','2025','1','29','multiple_choice','Які політичні сили наприкінці жовтня – початку листопада 1917 р. вели збройну боротьбу за владу в Києві?','[{"title":"Варіанти відповіді","options":[{"marker":"1","text":"Українська Центральна Рада, підтримана українізованими військовими частинами","images":[]},{"marker":"2","text":"більшовики, що спиралися на ради робітничих і солдатських депутатів","images":[]},{"marker":"3","text":"сердюцька дивізія гетьмана П. Скоропадського","images":[]},{"marker":"4","text":"анархістські збройні загони Н. Махна","images":[]},{"marker":"5","text":"прихильники Тимчасового уряду Росії, згуртовані навколо штабу Київського військового округу","images":[]},{"marker":"6","text":"частини Добровольчої армії генерала А. Денікіна","images":[]},{"marker":"7","text":"підрозділи Головного отамана Армії УНР","images":[]}]}]','1;2;5','Пояснення
 ТЕМА: Початок Української революції.
Українська Центральна Рада не визнала більшовицький переворот, унаслідок якого більшовики повалили Тимчасовий уряд.
Захопивши владу в Петрограді, Ленін і його соратники розпочали боротьбу за контроль над Україною. У Києві наприкінці жовтня – початку листопада 1917 року відбулися збройні сутички між штабом Київського військового округу, що підтримував Тимчасовий уряд, більшовицькими військовими частинами, що спиралися на ради робітничих і солдатських депутатів, й українськими частинами, сформованими з делегатів третього Всеукраїнського військового зʼїзду, які підтримували Українську Центральну Раду.
Боротьба закінчилася поразкою штабу й придушенням більшовицького повстання.
Правильна відповідь: 1, 2, 5.','[]','https://zno.osvita.ua/ukraine-history/669/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_his-1.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','caf1f26840837f3c1762b9e9fcdbdbf2191b7a2025643e549c3e83c70483fe85','1','official','multiple_choice',(SELECT id FROM topics WHERE subject_slug='history' AND name='Початок Української революції')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('history','Україна в період загострення кризи радянської системи','Україна після 1945 року',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-history-s1-q30','34340','history','2025','1','30','multiple_choice','Які поняття пов''язані з розвитком дисидентського руху в Україні в 1960-1970-ті рр.?','[{"title":"Варіанти відповіді","options":[{"marker":"1","text":"«дефіцит»","images":[]},{"marker":"2","text":"«самвидав»","images":[]},{"marker":"3","text":"«люстрація»","images":[]},{"marker":"4","text":"«правозахисник»","images":[]},{"marker":"5","text":"«гласність»","images":[]},{"marker":"6","text":"«тамвидав»","images":[]},{"marker":"7","text":"«розвинений соціалізм»","images":[]}]}]','2;4;6','Пояснення
 ТЕМА: Україна в період загострення кризи радянської системи.
Дисидентський рух в Україні – це опозиційний рух із кінця 50-х – до середини 80-х рр. XX ст., учасники якого виступали за демократизацію суспільства, дотримання прав і свобод людини, за національні права, власну державність.
Складником дисидентського руху в УРСР був правозахисний рух, зосереджений передусім на захисті прав і свобод громадян, гарантованих Конституціями СРСР та УРСР.
В умовах тоталітаризму його представники не мали змоги донести до широкого загалу свої позиції, що спонукало їх до несанкціонованого поширення власних наукових праць, публіцистики, літературних творів тощо. Так сформувалося явище самвидаву. Яскраві зразки самвидаву – це памфлет Євгена Сверстюка й Івана Світличного «З приводу процесу над Погружальським», «Інтернаціоналізм чи русифікація?» Івана Дзюби, «Лихо з розуму» В’ячеслава Чорновола, часопис «Український вісник» та ін.
Якщо самвидав виготовляли й поширювали в межах СРСР, то тамвидав – за кордоном. Поширення «антирадянської літератури» прирівнювали до тяжкого злочину, за який було передбачено суворе покарання, включно з тюремними термінами, засланнями й іншими формами репресій.
Правильна відповідь: 2, 4, 6.','[]','https://zno.osvita.ua/ukraine-history/669/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_his-1.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','a66f239c5336980da2f009f74eb2ccb6791e1a13e1c57b993a16e5fd65eae4b9','1','official','multiple_choice',(SELECT id FROM topics WHERE subject_slug='history' AND name='Україна в період загострення кризи радянської системи')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('history','Стародавня історія України','Стародавня та середньовічна Україна',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-history-s2-q1','34341','history','2025','2','1','single_choice','Розгляньте монету, присвячену видатній історико-культурній пам''ятці стародавньої історії України.
В оздобленні реверсу монети (зворотний бік) художник використав зображення пам''ятки, знайденої археологами під час розкопок','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"кургану Товста Могила.","images":[]},{"marker":"Б","text":"трипільського поселення.","images":[]},{"marker":"В","text":"Херсонесу Таврійського.","images":[]},{"marker":"Г","text":"Мізинської стоянки.","images":[]}]}]','a','Пояснення
 ТЕМА: Стародавня історія України.
В оздобленні реверсу монети художник зобразив пектораль – найвідоміший і найцінніший артефакт культури скіфів, який зберігають в Україні. Цю золоту нагрудну прикрасу 1971 року археолог Борис Мозолевський знайшов у кургані Товста Могила.
Пектораль складається з трьох ярусів, які відображають уявлення скіфів про світобудову й реалістично змальовують картини їхнього побуту. У центр стилізованої композиції художник помістив збільшені фрагменти верхнього ярусу прикраси: угорі – кобилу з лошам на вершині кургану, унизу – двох чоловіків, які тримають у руках розтягнуту овечу шкуру.
Правильна відповідь – А.','["/question-assets/history/34341-1.png"]','https://zno.osvita.ua/ukraine-history/670/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_his-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','53cc7f66feee2dbd2192100db78463a1dbcc0edf2b16927087a94b41e4013117','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='history' AND name='Стародавня історія України')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('history','Русь-Україна (Київська держава)','Стародавня та середньовічна Україна',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-history-s2-q2','34342','history','2025','2','2','single_choice','Розгляньте картосхему.
Організацію зображених на ній походів руських князів пов''язують із','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"Романом Мстиславовичем.","images":[]},{"marker":"Б","text":"Володимиром Мономахом.","images":[]},{"marker":"В","text":"Ярославом Осмомислом.","images":[]},{"marker":"Г","text":"Володимиром Глібовичем.","images":[]}]}]','b','Пояснення
 ТЕМА: Русь-Україна (Київська держава).
На картосхемі стрілками позначено напрямки походів об’єднаних князівських військ у степ, де панували кочовики-половці.
Після низки поразок і руйнівних набігів половців на Русь, які тривали протягом другої половини XI ст., руські князі на початку XII ст. перейшли в наступ. Вони не лише відбивали атаки кочівників на власній території, а й здійснювали в половецький степ переможні походи, ініціатором й обов’язковим учасником яких був переяславський князь Володимир Мономах.
Унаслідок низки походів 1103–1111 років половці надовго втратили ініціативу, тому не могли диктувати свої умови правителям Русі.
Правильна відповідь – Б.','["/question-assets/history/34342-1.png"]','https://zno.osvita.ua/ukraine-history/670/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_his-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','6e1dbd966dcc765aa1fa4e86a379ae5369f6b59a13973d4eeb9b7fbed0e3c5b1','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='history' AND name='Русь-Україна (Київська держава)')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
