INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-history-s2-q3','34343','history','2025','2','3','single_choice','Пріоритет у зовнішній політиці князя Данила Романовича в другій половині 1240-х – 1260-х рр. полягав у','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"розширенні території держави за рахунок володінь Угорського королівства.","images":[]},{"marker":"Б","text":"здобутті великокнязівського столу у Великому князівстві Литовському для свого сина Лева.","images":[]},{"marker":"В","text":"зміцненні союзу з Королівством Польським для відсічі агресії Тевтонського ордену.","images":[]},{"marker":"Г","text":"створенні коаліції європейських держав для боротьби із Золотою Ордою.","images":[]}]}]','d','Пояснення
 ТЕМА: Королівство Руське (Галицько-Волинська держава). Монгольська навала.
Після навали орд хана Батия в 1237–1241 рр. на Русь князь Данило Романович 1245 року змушений був їхати в Сарай за ярликом. Відтоді пріоритетним завданням для князя стало позбавлення залежності від Золотої Орди.
Для цього він посилював своє військо, укріплював міста, шукав союзників поміж інших руських князів, намагався створити антимонгольську коаліцію європейських держав, вів перемовини з папою Римським Інокентієм IV щодо організації хрестового походу проти монголів.
Правильна відповідь – Г.','[]','https://zno.osvita.ua/ukraine-history/670/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_his-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','56b857bf76afc20c52bea8e7c6562439e4b44646f118ecec572d0599eb17b9f4','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='history' AND name='Королівство Руське (Галицько-Волинська держава). Монгольська навала')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('history','Українські землі у складі Речі Посполитої в другій половині XVI ст.','Ранньомодерна Україна',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-history-s2-q4','34344','history','2025','2','4','single_choice','З ким з історичних постатей пов''язана зображена архітектурна пам''ятка?','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"","images":["/question-assets/history/34344-o1-1.png"]},{"marker":"Б","text":"","images":["/question-assets/history/34344-o2-1.png"]},{"marker":"В","text":"","images":["/question-assets/history/34344-o3-1.png"]},{"marker":"Г","text":"","images":["/question-assets/history/34344-o4-1.png"]}]}]','c','Пояснення
 ТЕМА: Українські землі в складі Речі Посполитої в другій половині XVI ст.
На фото зображено Круглу (Нову) вежу Острозького замку – унікальну пам’ятку оборонної архітектури середньовічної Волині.
Острозький замок – родовий маєток князів Острозьких. На тлі яскравих представників цього роду на особливу увагу заслуговує постать Василя-Костянтина, завдяки якому Острог став осередком української культури та духовності.
Тут князь заснував перший у Східній Європі вищий навчальний заклад – словʼяно-греко-латинську школу; за його сприяння було видано Острозьку Біблію; під його покровительством розвивалася полемічна література.
А портрет гетьмана Богдана Хмельницького
Б портрет гетьмана Івана Мазепи
В портрет князя Василя-Костянтина Острозького
Г портрет гетьмана Петра Конашевича-Сагайдачного
Правильна відповідь – В.','["/question-assets/history/34344-1.png"]','https://zno.osvita.ua/ukraine-history/670/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_his-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','ac9e8e68c18dfb4a91cb7e6550831a828c859f6146121a5ca626c46db84f61d8','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='history' AND name='Українські землі у складі Речі Посполитої в другій половині XVI ст.')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('history','Козацька Україна наприкінці 50–80-х рр. XVII ст.','Ранньомодерна Україна',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-history-s2-q5','34345','history','2025','2','5','single_choice','Що спонукало гетьмана Петра Дорошенка до укладення такого договору: «Щоб наш гетьман завжди був утверджений у своїй достойності аж до останнього дня життя свого так, щоб його ніхто не міг із султанової влади перемінити і з престолу його скинути... Нехай не учинить султан турецький мир, а ні хан татарський... із королем польським і з царем московським, союзу дружнього нехай не творить без відома та згоди нашого гетьмана й всього козацького війська...»?','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"нестача ресурсів для одночасної боротьби проти кількох противників","images":[]},{"marker":"Б","text":"поширення ісламу серед широких верств населення українських земель","images":[]},{"marker":"В","text":"особисті зобов''язання гетьмана перед кримським ханом","images":[]},{"marker":"Г","text":"необхідність оформлення спадкової влади в Ханській Україні","images":[]}]}]','a','Пояснення
 ТЕМА: Козацька Україна наприкінці 50-80-х рр. XVII ст.
Правильна відповідь — нестача ресурсів для одночасної боротьби проти кількох противників.
В умові наведено уривок Корсунських статей 1669 року, у яких визначено статус Війська Запорозького як держави під протекторатом турецького султана Мехмеда IV.
Завдяки цій угоді Петро Дорошенко сподівався об''єднати українські землі й захистити їх від польської і московської агресії.
Цьому рішенню передувало Андрусівське перемирʼя 1667 року, умовами якого було закріплено поділ Гетьманщини по Дніпру між Московським царством і Річчю Посполитою.
Саме тому гетьман звернувся за підтримкою до третьої сили – Османської імперії.
Правильна відповідь – А.','[]','https://zno.osvita.ua/ukraine-history/670/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_his-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','7349d6124a2547246f80274735849ffdced81333999dddf26529f542414e4a1a','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='history' AND name='Козацька Україна наприкінці 50–80-х рр. XVII ст.')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('history','Українські землі наприкінці XVII – у першій половині XVIII ст.','Ранньомодерна Україна',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-history-s2-q6','34346','history','2025','2','6','single_choice','Результатом Північної війни для Гетьманщини стало','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"нищення її автономних прав.","images":[]},{"marker":"Б","text":"ліквідація «Правління гетьманського уряду».","images":[]},{"marker":"В","text":"розпуск козацьких полків.","images":[]},{"marker":"Г","text":"скасування посади гетьмана.","images":[]}]}]','a','Пояснення
 ТЕМА: Українські землі в кінці XVII – першій половині XVIII ст.
Результатом Північної війни для Гетьманщини стало нищення її автономних прав.
Після поразки шведського війська в Полтавській битві московська влада посилила контроль над українськими землями. Козацьку автономію була жорстко обмежено:
 Діяльність гетьмана контролював царський резидент;
 Урізано економічні права;
 Тривали репресії проти ймовірних прихильників Мазепи;
 Малоросійська колегія стала вищим органом контролю Гетьманщини. 
Правильна відповідь – А.','[]','https://zno.osvita.ua/ukraine-history/670/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_his-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','8c79f1e6802a19cb64225bf7ae8bf1e054f8c4cdec844aa4682a1360fa3ddcdc','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='history' AND name='Українські землі наприкінці XVII – у першій половині XVIII ст.')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('history','Українські землі наприкінці XVII – у першій половині XVIII ст.','Ранньомодерна Україна',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-history-s2-q7','34347','history','2025','2','7','single_choice','На пам''ятній монеті зображено','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"видатного архітектора доби бароко.","images":[]},{"marker":"Б","text":"останнього гетьмана Війська Запорозького.","images":[]},{"marker":"В","text":"останнього кошового отамана Запорозької Січі.","images":[]},{"marker":"Г","text":"полководця та очільника Малоросійської колегії.","images":[]}]}]','b','Пояснення
 ТЕМА: Українські землі в кінці XVII – першій половині XVIII ст.
На реверсі монети в центрі зображено портрет Кирила Розумовського – останнього гетьмана Війська Запорозького.
Розумовський прагнув зберегти традиційний козацький устрій Гетьманщини й докладав зусиль до розбудови її автономії: провів адміністративну, судову, військову реформи, запровадив Генеральне зібрання козацької старшини для обговорення важливих справ і проєктів державних реформ тощо.
Його прагнення призначати полковників на власний розсуд і підтримувати дипломатичні відносини із сусідніми державами викликали занепокоєння в Петербурзі. Після приходу до влади Катерини II гетьманство було ліквідовано 1764 року.
Правильна відповідь – Б.','["/question-assets/history/34347-1.png"]','https://zno.osvita.ua/ukraine-history/670/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_his-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','5c1cd1eedc04ba088414d8531a9c831a8c35f3f1268fe0da951e324cdfac3ed4','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='history' AND name='Українські землі наприкінці XVII – у першій половині XVIII ст.')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('history','Українські землі у складі Російської імперії наприкінці XVIII – у першій половині XIX ст.','Українські землі у складі імперій',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-history-s2-q8','34348','history','2025','2','8','single_choice','Прочитайте уривок історичного джерела.
«У майбутньому Слов''янському союзі, у який ми віримо та якого сподіваємося, наша Південна Русь повинна становити окрему державну цілість на всьому просторі, де народ говорить українською мовою.., заснованої не на згубній, мертвій централізації, а на ясній свідомості рівноправності та своєї власної користі... Нехай же ні росіяни, ні поляки не вважають своїми землі, заселені нашим народом...»
У цитованому документі відображено засади діяльності','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"Київської громади.","images":[]},{"marker":"Б","text":"Товариства українських поступовців.","images":[]},{"marker":"В","text":"Братства тарасівців.","images":[]},{"marker":"Г","text":"Кирило-Мефодіївського братства.","images":[]}]}]','d','Пояснення
 ТЕМА: Українські землі в складі Російської імперії наприкінці XVIII – у першій половині XIX ст.
У цитованому документі відображено засади діяльності Кирило-Мефодіївського братства (1846–1847 рр.) – української таємної політичної організації, заснованої в Києві Василем Білозерським, Миколою Гулаком, Миколою Костомаровим, Пантелеймоном Кулішем тощо.
Основне завдання братства полягало в побудові майбутнього суспільства на засадах християнської моралі через здійснення реформ. Братчики прагнули створення демократичної федерації суверенних слов''янських республік на чолі з Україною. Вони виступали за знищення царизму, скасування кріпосного права та станів, забезпечення рівноправності всіх слов''янських мов, розвиток культури й освіти.
Правильна відповідь – Г.','[]','https://zno.osvita.ua/ukraine-history/670/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_his-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','40b41f40848124cedd826886473e32a4364348d784d0fb914ac4e4dcb02060c4','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='history' AND name='Українські землі у складі Російської імперії наприкінці XVIII – у першій половині XIX ст.')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('history','Культура України кінця XVIII – першої половини XIX ст.','Українські землі у складі імперій',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-history-s2-q9','34349','history','2025','2','9','single_choice','Хто є автором цитованого листа до О. Бодянського: «..ще ось що, чи я вам розказував, що я хочу рисовать нашу Украйну... Я її нарисую в трьох книгах, у першій будуть види, чи то по красі своїй, чи по історії прикметні, у другій – теперішній людський бит, а в третій – історія. Три естампи [офорти] уже готові – Печерська Київська криниця", "Судня в селі рада" і "Дари Богданові й українському народові". В год буде виходити 10 картин.., тексти буду писати сам або Куліша проситиму, а за історію потурбуйтесь... писать три листочки в год...»?','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"Василь Тропінін","images":[]},{"marker":"Б","text":"Тарас Шевченко","images":[]},{"marker":"В","text":"Василь Штернберг","images":[]},{"marker":"Г","text":"Микола Костомаров","images":[]}]}]','b','Пояснення
 ТЕМА: Культура України кінця XVIII – першої половини XIX ст.
Автором цитованого листа є Тарас Шевченко. Подорожуючи Україною, він зробив багато зарисовок, ескізів, етюдів, начерків, малюнків, що навело його на думку створити періодичне видання під назвою «Живописна Україна».
Розпочавши роботу над виданням, Шевченко звертається листовно до різних осіб із проханням про допомогу.
Наприкінці 1844 року в Петербурзі вийшов перший і останній випуск видання «Живописна Україна» з такими шістьма офортами (гравюрами) Шевченка: «Дари в Чигирині 1649 року», «Судня рада», «Старости», «Видубицький монастир», «Казка» та «У Києві».
Правильна відповідь – Б.','[]','https://zno.osvita.ua/ukraine-history/670/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_his-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','d7e03b21c6d78b555d41291535fde3d3cae978f42ec80072f05dbb0013dbebba','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='history' AND name='Культура України кінця XVIII – першої половини XIX ст.')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('history','Українські землі у складі Австро-Угорщини в другій половині XIX ст.','Українські землі у складі імперій',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-history-s2-q10','34350','history','2025','2','10','single_choice','З яких регіонів України в другій половині ХІХ ст. переважала трудова еміграція на Захід?','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"Галичини, Закарпаття, Буковини","images":[]},{"marker":"Б","text":"Поділля, Київщини, Волині","images":[]},{"marker":"В","text":"Таврії, Донбасу","images":[]},{"marker":"Г","text":"Слобожанщини, Придніпров''я","images":[]}]}]','a','Пояснення
 ТЕМА: Українські землі в складі Австро-Угорщини в другій половині XIX ст.
В українських регіонах Австро-Угорщини – Галичині, Закарпатті, Буковині – у другій половині XIX ст. виник великий надлишок робочої сили.
Малоземелля, економічна залежність від великих землевласників і лихварів призводили до того, що збіднілі селяни були вимушені продавати свої наділи.
Розвиток залізничного транспорту забезпечив приплив дешевих і якісних товарів західної промисловості до українських земель. Більшість місцевих виробників, не витримавши жорсткої конкуренції, закрили свої виробництва. Безробіття та зубожіння стали масовим явищем.
Уряди США, Канади, Бразилії, Аргентини й інших країн із величезними сільськогосподарськими ресурсами й браком робочої сили заохочували масовий приплив працездатних людей. Сотні тисяч українців стали емігрантами.
Правильна відповідь – А.','[]','https://zno.osvita.ua/ukraine-history/670/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_his-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','d079502664b8d9a373bc1fbff1d63082681a51d00f318457b42154b164008ee0','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='history' AND name='Українські землі у складі Австро-Угорщини в другій половині XIX ст.')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('history','Українські землі у складі Російської імперії в 1900–1914 рр.','Українські землі у складі імперій',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-history-s2-q11','34351','history','2025','2','11','single_choice','У 2017 році Український інститут національної пам''яті з нагоди 100-річчя подій Української революції 1917-1921 рр. і вшанування пам''яті її учасників презентував плакати-банери соціальної рекламної кампанії «100 років боротьби. Українська революція».
Яку характеристику-резюме діяча треба розмістити у відповідному полі наведеного плаката-банера?','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"меценат, колекціонер, підприємець, член Загальноросійського товариства цукрозаводчиків, голова правління Київського товариства старожитностей і мистецтв","images":[]},{"marker":"Б","text":"громадський діяч, агроном, меценат української культури, публіцист, видавець українських щоденних газет на Наддніпрянщині – «Громадська Думка» та «Рада»","images":[]},{"marker":"В","text":"землевласник, меценат, голова Південно-Західного відділу Російського географічного товариства, засновник колегії в Києві, гімназій в Прилуках","images":[]},{"marker":"Г","text":"промисловець, інженер-технолог у галузі цукроваріння, меценат української культури, фінансував видання часописів «Київська старовина», «Україна»","images":[]}]}]','b','Пояснення
 ТЕМА: Українські землі в складі Російської імперії в 1900–1914 рр.
Євген Чикаленко – унікальна постать українського національного руху. Успішний агроном і землевласник, він спрямовував величезні власні кошти на фінансування українських культурних проєктів, чи не найважливішим із яких була перша щоденна газета Наддніпрянської України «Громадська думка» (згодом «Рада»). «Рада» стала голосом українського руху й готувала українську інтелігенцію до боротьби за національне визволення.
На початку 1917 року Чикаленко став одним з ініціаторів створення Української Центральної Ради.
Правильна відповідь – Б.','["/question-assets/history/34351-1.png"]','https://zno.osvita.ua/ukraine-history/670/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_his-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','04b223d93cf01e9e1690fe0fc85972c01a20a778f8be7b5fe250fe53ad89b1a9','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='history' AND name='Українські землі у складі Російської імперії в 1900–1914 рр.')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('history','Україна в роки Першої світової війни','Війна та Українська революція',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-history-s2-q12','34352','history','2025','2','12','single_choice','Події якого року Першої світової війни відображено на карикатурі?','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"1915 р.","images":[]},{"marker":"Б","text":"1916 р.","images":[]},{"marker":"В","text":"1917 р.","images":[]},{"marker":"Г","text":"1918 р.","images":[]}]}]','b','Пояснення
 ТЕМА: Україна в роки Першої світової війни.
У карикатурі часів Першої світової війни автор гротескно змальовує проблемну ситуацію для військ Четверного союзу: безпорадний вояка, як у пастці, застряв руками у Вердені, а ногами – на Східному фронті, отримуючи дошкульних ударів багнетами.
Очевидно, що карикатура візуалізує успіхи на фронті російської армії під час Брусиловського прориву 1916 року, унаслідок якого під контроль російського війська перейшли частина Волині, Галичини й Буковина.
Інші пропоновані варіанти не відповідають змісту карикатури.
На Східному фронті 1915 року австро-угорська й німецька армії відкинули російську армію на схід під час Горлицького прориву.
Червневий наступ російського війська 1917 року завершився провалом.
Для 1918 року характерна відсутність бойових дій на Східному фронті через укладення в Брест-Литовську державами Четверного союзу договорів з УНР і Радянською Росією.
Правильна відповідь – Б.','["/question-assets/history/34352-1.png"]','https://zno.osvita.ua/ukraine-history/670/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_his-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','30e3089befd9252ca42295f8cfca7c77633effbef7e048575be1eedd8c4494bb','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='history' AND name='Україна в роки Першої світової війни')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('history','Розгортання Української революції. Боротьба за відновлення державності','Війна та Українська революція',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-history-s2-q13','34353','history','2025','2','13','single_choice','Що спричинило ситуацію, описану в уривку джерела:
«Винниченко волів би говорити з Леніним та Чичеріним (нарком закордонних справ РСФРР – ред.), але я [Симон Петлюра], Панас Андрієвський та Андрій Макаренко (члени Директорії), маємо іншу думку. Нам треба спертися об захід, на аліянтів [союзників, Антанту]...»?','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"Перша війна радянської Росії проти України","images":[]},{"marker":"Б","text":"антигетьманське повстання","images":[]},{"marker":"В","text":"Друга війна радянської Росії проти України","images":[]},{"marker":"Г","text":"радянсько-польська війна","images":[]}]}]','c','Пояснення
 ТЕМА: Розгортання Української революції. Боротьба за відновлення державності.
В уривку окреслено розбіжності в позиціях членів Директорії щодо реакції на дії більшовицького Тимчасового робітничо-селянського уряду України, війська якого ще в грудні 1918 року розпочали наступ на Україну.
Уряд Директорії не зумів зорганізувати оборону країни й обмежився численними нотами протесту в бік Росії. Лише 16 січня 1919 року, через тиждень після отримання відповіді від наркома (міністра) закордонних справ Росії Георгія Чичеріна, що військ РСФРР на території України нема, а війну проти УНР веде цілком незалежний український радянський уряд, Директорія Української Народної Республіки оголосила війну більшовицькій Росії.
Після відставки Винниченка з посади голови Директорії, зміни урядів, Директорія УНР припинила існування як колективний орган. Головному отаману Армії УНР Симону Петлюрі попри допомогу Польщі не вдалось врятувати УНР від поразки у війні.
Правильна відповідь – В.','[]','https://zno.osvita.ua/ukraine-history/670/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_his-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','7af4fbb3be5a2314388736af70a6ddf51903681da6d7e4aacf544d9ff6e770f9','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='history' AND name='Розгортання Української революції. Боротьба за відновлення державності')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
