INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-history-s2-q14','34354','history','2025','2','14','single_choice','Що стало результатом державної політики в галузі культури в СРСР та УРСР наприкінці 1930-х рр.?','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"розквіт авангардних напрямів у мистецтві","images":[]},{"marker":"Б","text":"утвердження ідейного різноманіття в мистецтві","images":[]},{"marker":"В","text":"скасування цензури засобів масової інформації","images":[]},{"marker":"Г","text":"ліквідація масової неписьменності дорослих","images":[]}]}]','d','Пояснення
 ТЕМА: Утвердження більшовицького тоталітарного режиму в Україні.
Культурне життя в радянській Україні 1930-х років було повністю зумовлено тоталітарним політичним режимом. Воно мало суперечливий характер: поряд із наростанням політичного терору проти культури і її творців певний час зберігалася інерція позитивних процесів, започаткованих у попередньому десятилітті. Зокрема культурний поступ було позначено реальними здобутками в ліквідації неписьменності (лікнепі).
Лікнеп – система заходів в СРСР й УСРР для навчання грамоти всього неписьменного населення, яку було започатковано постановою уряду УСРР «Про боротьбу з неписьменністю» від 21 травня 1921 р. Це була не лише освітня, а й ідеологічна кампанія.
Навчали грамоти в державних школах лікнепу, пунктах лікнепу різних громадських організацій і товариств, зокрема через мережу товариства «Геть неписьменність», гуртках, у яких письменні навчали неписьменних.
Згідно з даними всесоюзного перепису населення 1937 р., в УРСР 85,6 % мешканців вважалися грамотними (1926 р. таких було 52,6 %).
Правильна відповідь – Г.','[]','https://zno.osvita.ua/ukraine-history/670/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_his-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','8df77064fc228eaa9c0eac2ca270bf6b9180c59c5ded7d980de50c8353eedc93','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='history' AND name='Утвердження більшовицького тоталітарного режиму в Україні')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
