INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-history-s2-q16','34356','history','2025','2','16','single_choice','Який плакат створено в роки Другої світової війни?','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"","images":["/question-assets/history/34356-o1-1.png"]},{"marker":"Б","text":"","images":["/question-assets/history/34356-o2-1.png"]},{"marker":"В","text":"","images":["/question-assets/history/34356-o3-1.png"]},{"marker":"Г","text":"","images":["/question-assets/history/34356-o4-1.png"]}]}]','c','Пояснення
 ТЕМА: Початок Української революції. Встановлення комуністичного тоталітарного режиму в Україні. Утвердження більшовицького тоталітарного режиму в Україні. Україна в роки Другої світової війни.
А Пропагандистський плакат часів політики воєнного комунізму, заходом якої було впровадження загальної трудової повинності для всього працездатного населення.
Б На плакаті відображено різні аспекти індустріалізації і колективізації часів сталінської модернізації.
В Плакат, створений у роки Другої світової війни, мотивував населення самовіддано трудитися задля перемоги.
Г Кольорову листівку-плакат створено наприкінці 1917 року після проголошення Третім універсалом Української Народної Республіки (УНР).
Правильна відповідь – В.','[]','https://zno.osvita.ua/ukraine-history/670/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_his-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','96b0cd94fef61485c61f6c7e72af6de4d51f6e13e5da2ddf554ffc3ca4e86eb3','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='history' AND name='Міжтематичні завдання з історії України')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
