INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-history-s2-q17','34357','history','2025','2','17','single_choice','У якій галузі мистецтва уславилися Тетяна Яблонська, Катерина Білокур, Марія Примаченко?','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"кінематографі","images":[]},{"marker":"Б","text":"живописі","images":[]},{"marker":"В","text":"літературі","images":[]},{"marker":"Г","text":"архітектурі","images":[]}]}]','b','Пояснення
 ТЕМА: Україна в перші повоєнні роки. Україна в умовах десталінізації. Україна в період загострення кризи радянської системи.
Тетяна Яблонська, Катерина Білокур, Марія Примаченко – видатні українські художниці.
Катерина Білокур і Марія Примаченко – яскраві представниці жанру наївного мистецтва. Катерина Білокур найбільше малювала квіти («Хата в Богданівці»).
Марія Примаченко відома своїми картинами з чудернацькими, фантастичними тваринами («Гороховий звір»).
Тетяна Яблонська стала символом українського соцреалістичного живопису. Її найвідоміша картина «Хліб» стала одним із найтитулованіших творів у Радянському Союзі.
Правильна відповідь – Б.','[]','https://zno.osvita.ua/ukraine-history/670/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_his-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','d44e704a6cf3a71fccd5f0449172461f91c20082f30410e704e06c155e70256f','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='history' AND name='Міжтематичні завдання з історії України')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
