INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-history-s2-q18','34358','history','2025','2','18','single_choice','Проголошення керівництвом СРСР курсу на «зближення та злиття. націй у "нову історичну спільноту – радянський народ"...» призвело до','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"збільшення в школах кількості навчальних годин з історії України.","images":[]},{"marker":"Б","text":"зростання в суспільстві інтересу до надбань української культури.","images":[]},{"marker":"В","text":"посилення процесу русифікації та скорочення сфери вживання української мови.","images":[]},{"marker":"Г","text":"скасування цензури на літературні твори мовами національних меншин.","images":[]}]}]','c','Пояснення
 ТЕМА: Україна в період загострення кризи радянської системи.
Проголошення керівництвом СРСР курсу на «зближення та злиття націй у "нову історичну спільноту – радянський народ"...» було спрямовано на формування єдиної «радянської нації».
Інтернаціоналізація мала замінити національну ідентичність через культурну асиміляцію, русифікацію s нівелювання національних відмінностей.
Російську мову позиціювали як мову міжнаціонального спілкування. В освіті її зробили привілейованою, закріпивши це постановами ЦК КПРС і Ради Міністрів СРСР «Про подальше вдосконалення вивчення і викладання російської мови в союзних республіках» і «Про подальші заходи щодо вивчення російської мови в загальноосвітніх школах та інших навчальних закладах союзних республік».
Так само у сфері культури та мистецтва російська до середини 80-х планомірно витісняла українську мову.
Правильна відповідь – В.','[]','https://zno.osvita.ua/ukraine-history/670/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_his-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','5818e546e20ff175b1fd42c08d0a1ee75f4306677d24d8f8a5bfa6202c317eb7','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='history' AND name='Україна в період загострення кризи радянської системи')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('history','Відновлення незалежності України','Незалежна Україна',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-history-s2-q19','34359','history','2025','2','19','single_choice','На якому фото зображено автора Акта проголошення незалежності України?','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"","images":["/question-assets/history/34359-o1-1.png"]},{"marker":"Б","text":"","images":["/question-assets/history/34359-o2-1.png"]},{"marker":"В","text":"","images":["/question-assets/history/34359-o3-1.png"]},{"marker":"Г","text":"","images":["/question-assets/history/34359-o4-1.png"]}]}]','a','Пояснення
 ТЕМА: Відновлення незалежності України.
Автором Акта проголошення незалежності України був Левко Лук''яненко – дисидент, співзасновник Української Гельсінської групи, лідер Української республіканської партії, народний депутат Верховної Ради.
Після спроби державного заколоту в Москві в серпні 1991 року він був серед тих, хто вимагав негайного проголошення незалежності України. Поки тривали дебати у Верховній Раді, Лук’яненко на аркуші шкільного зошита написав чернетковий проєкт документа, що стосувався незалежності України. Позачергова сесія Верховної Ради УРСР 24 серпня 1991 року ухвалила Акт проголошення незалежності України.
Правильна відповідь – А.','[]','https://zno.osvita.ua/ukraine-history/670/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_his-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','c9550ed8e50b6b2a85e9a1fe6bb14dbf96844b7b40ad914787adb6da528c6e11','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='history' AND name='Відновлення незалежності України')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('history','Творення нової України','Незалежна Україна',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-history-s2-q20','34360','history','2025','2','20','single_choice','Визначте подію, що стала наслідком геополітичного вибору України, варіанти якого візуалізує карикатура.','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"початок Революції Гідності","images":[]},{"marker":"Б","text":"проголошення незалежності України","images":[]},{"marker":"В","text":"розгортання Революції на граніті","images":[]},{"marker":"Г","text":"прийняття Декларації про державний суверенітет України","images":[]}]}]','a','Пояснення
 ТЕМА: Творення нової України.
Автор карикатури візуалізує два вектори української геополітики часів президентства В. Януковича та прогнозує перспективи для України, повʼязані з ними.
Тривалий час міжнародна політика України проходила під знаком утвердження євроінтеграційного курсу. Водночас важливими геополітичним вектором залишалися відносини з Росією.
Однак негативна реакція Москви на підготовку до підписання Україною Угоди про асоціацію з Європейським Союзом призвела спочатку до різкого гальмування євроінтеграційних процесів в Україні, а потім і до повного розвороту в бік Росії та дистанціювання від них. Москва добивалася приєднання України до Митного союзу – форми торгівельно-економічної інтеграції країн Євразійського економічного союзу.
Відмова Януковича підписати Угоду про асоціацію з Євросоюзом на саміті «Східного партнерства» у Вільнюсі спричинила мирні протести в Києві й регіонах, які було розпочато 21 листопада 2013 року. Євроінтеграційні гасла дали акції назву Євромайдан.
Після силового розгону 30 листопада Євромайдан став рушієм кардинальних змін у країні, запустив процес повного оновлення державної системи й отримав назву Революція Гідності.
Правильна відповідь – А.','["/question-assets/history/34360-1.png"]','https://zno.osvita.ua/ukraine-history/670/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_his-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','1c0f186c6411144fc708ab86f43549e74f04f4d9f45b9bb94e901bcd9047909f','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='history' AND name='Творення нової України')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('history','Русь-Україна (Київська держава)','Стародавня та середньовічна Україна',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-history-s2-q21','34361','history','2025','2','21','matching','Увідповідніть уривок історичного джерела (1-4) з його назвою (А – Д).','[{"title":"Варіанти відповіді","options":[{"marker":"1","text":"«Костянтин з матір''ю своєю, Єленою, хрест із Єрусалима приніс... Ти ж із своєю бабусею, Ольгою, принесли хрест від нового Єрусалима – Костянтинограда, по всій землі своїй розставивши, утвердили віру християнську...»","images":[]},{"marker":"2","text":"«Якщо вдарить мечем не на смерть, то має заплатити 3 гривні... а потерпілому – гривню за рану, як лікувальне. Коли ж уб''є на смерть, то платити віру...»","images":[]},{"marker":"3","text":"«Й ті ж словяни, прийшовши, сіли по Дніпру і назвалися полянами, а інші – деревлянами, бо осіли в лісах... Другі ж сіли на Десні, і по Сейму, і по Сулі і називалися сіверянами...»","images":[]},{"marker":"4","text":"«А найголовніше – убогих не забувайте, а скільки можете, ...годуйте і подайте милостиню сироті, і вдовицю оправдуйте самі, не давайте сильним погубити людину...»","images":[]}]},{"title":"Варіанти відповіді","options":[{"marker":"А","text":"«Руська правда»","images":[]},{"marker":"Б","text":"«Повчання дітям»","images":[]},{"marker":"В","text":"«Слово про Закон і Благодать»","images":[]},{"marker":"Г","text":"«Повість минулих літ»","images":[]},{"marker":"Д","text":"«Слово о полку Ігоревім»","images":[]}]}]','1c;2a;3d;4b','Пояснення
 ТЕМА: Русь-Україна (Київська держава)
1 – В: «Слово про Закон і Благодать» – видатна пам’ятка давньоруської літератури XI ст. авторства митрополита Іларіона. Твір є богословським трактатом і панегіриком на честь хрещення Русі-України та діяльності князів Володимира і Ярослава.
Іларіон пише, що прийняття Руссю хрещення та святість наших князів не були випадковим явищем, а ознакою особливого благовоління Божого до нашого краю. Він стверджує, що саме християнство об’єднало розрізнені слов’янські племена в один народ, а Київську державу зробило рівноправною серед християнських держав.
У наведеному уривку Іларіон прирівнює князя Володимира Великого до першого християнського імператора Костянтина Великого, а княгиню Ольгу – до матері Костянтина.
2 – А: «Руська правда» – перший писаний кодифікаційний звід руського права, створення якого пов’язують з іменами Ярослава Мудрого та його нащадків.
Давньоруський кодекс регулював широкий спектр суспільних відносин, містив норми, що суттєво обмежували феодальну сваволю, хоча й закріплювали соціальну нерівність.
«Руська правда» є свідченням високого рівня правової культури Київської держави. Зокрема в ній було введено обмеження, а згодом і заборону звичаєвого права кровної помсти, яку замінено грошовою компенсацією.
 3 – Г: «Повість минулих літ» – пам''ятка літописання Русі-України (Київської держави). За однією з версій літопис створювали протягом тривалого часу, аж поки на початку XII ст. на основі попередніх зведень його завершив, упорядкував і дав йому назву чернець Києво-Печерського монастиря Нестор.
Цей твір є важливим джерелом вивчення середньовічної історії України. Зокрема в ньому автор переповідає історію розселення східнословʼянських племен.
4 – Б: «Повчання дітям» – своєрідний політичний заповіт Володимира Мономаха своїм нащадкам. У ньому князь висловлює думки загальнодержавного, політичного і морального характеру, формує ідеальний образ правителя, який власною поведінкою повинен подавати приклад іншим.
Правильна відповідь: 1 – В, 2 – А, 3 – Г, 4 – Б.','[]','https://zno.osvita.ua/ukraine-history/670/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_his-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','13a454a51eae135817ef5cc0156a24e80a0b9d11131354a2f9ab989e8ec08561','1','official','matching',(SELECT id FROM topics WHERE subject_slug='history' AND name='Русь-Україна (Київська держава)')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('history','Міжтематичні завдання з історії України','Узагальнення',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-history-s2-q22','34362','history','2025','2','22','matching','Увідповідніть термін (1-4) з його визначенням (А – Д).','[{"title":"Варіанти відповіді","options":[{"marker":"1","text":"«весна народів»","images":[]},{"marker":"2","text":"«громадівський рух»","images":[]},{"marker":"3","text":"«Братство тарасівців»","images":[]},{"marker":"4","text":"«Київська козаччина»","images":[]}]},{"title":"Варіанти відповіді","options":[{"marker":"А","text":"таємна політична організація, яка крім культурно-просвітницької діяльності, культивування ідей Шевченка, висувала політичні постулати визволення української нації з-під московського ярма","images":[]},{"marker":"Б","text":"революційний рух, який ставив за мету знищення феодальної форми правління і створення незалежних національних держав у Європі","images":[]},{"marker":"В","text":"масовий селянський рух в Україні, спричинений поширенням чуток про звільнення селян від кріпацтва у разі їхнього вступу до ополчення під час чергової російсько-турецької війни","images":[]},{"marker":"Г","text":"рух, що існував у формі національно-культурних осередків української інтелігенції, програма якого передбачала: демократизм, федералізм, європеїзм, культурництво та еволюційність","images":[]},{"marker":"Д","text":"національні добровільні військово-міліційні формування, головним завданням яких була організація оборони народу та охорони ладу під час Української революції","images":[]}]}]','1b;2d;3a;4c','Пояснення
 ТЕМА: Українські землі в складі Австрійської імперії наприкінці XVIII – у першій половині XIX ст. Українські землі в складі Російської імперії в другій половині XIX ст.
1 – Б: «весна народів» – революційний рух 1848-1849 рр., який охопив більшість країн Європи. В його основі було закладено ідеї ліберальних конституційних реформ, ліквідації старих феодальних порядків і побудови національних держав.
2 – Г: громадівський рух – національно-культурний рух в Наддніпрянській Україні наприкінці 1850–1890-х рр., спрямований на відродження української освіти, науки, культури та формування національної свідомості українців в умовах імперського панування.
3 – А: Братство тарасівців – перша українська політична організація, члени якої 1892 року здійснили подорож до Канева й на могилі Тараса Шевченка поклялися поширювати серед українського народу самостійницькі ідеї і боротися за незалежність України. Братство тарасівців було перехідною сходинкою від громадівського руху до організації національних українських партій.
4 – В: Київська козаччина – масовий селянський рух 1855 року під час Кримської війни, поштовхом до якого стало оприлюднення маніфестів царського уряду про створення державного ополчення, у разі вступу до якого селяни сподівалися на звільнення від кріпацтва. Рух охопив частину повітів Київської губернії. Селяни повсюдно відмовлялися виконувати панщину й вимагали записати їх у козаки. Виступ було жорстоко придушено.
Правильна відповідь: 1 – Б, 2 – Г, 3 – А, 4 – В.','[]','https://zno.osvita.ua/ukraine-history/670/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_his-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','4bd9fa360f6c64695bda94813c14572e59805b860b23b21b60d4824e26c3a2ff','1','official','matching',(SELECT id FROM topics WHERE subject_slug='history' AND name='Міжтематичні завдання з історії України')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('history','Західноукраїнські землі в міжвоєнний період','Міжвоєнна доба і Друга світова війна',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-history-s2-q23','34363','history','2025','2','23','matching','Кому з діячів (1-4) належить наведений факт біографії (А – Д)?','[{"title":"Варіанти відповіді","options":[{"marker":"1","text":"Євген Коновалець","images":[]},{"marker":"2","text":"Дмитро Донцов","images":[]},{"marker":"3","text":"Василь Мудрий","images":[]},{"marker":"4","text":"Августин Волошин","images":[]}]},{"title":"Варіанти відповіді","options":[{"marker":"А","text":"президент Карпатської України","images":[]},{"marker":"Б","text":"перший голова Організації українських націоналістів","images":[]},{"marker":"В","text":"один із засновників Української національної партії Буковини","images":[]},{"marker":"Г","text":"ідеолог українського інтегрального націоналізму","images":[]},{"marker":"Д","text":"секретар Таємного українського університету у Львові","images":[]}]}]','1b;2d;3e;4a','Пояснення
 ТЕМА: Західноукраїнські землі в міжвоєнний період.
1 – Б: Євген Коновалець – борець за незалежність України, ініціатор створення Галицько-Буковинського куреня січових стрільців – однієї з найбоєздатніших частин Армії УНР, лідер Української військової організації (УВО), перший голова Проводу Організації Українських Націоналістів (ОУН).
2 – Г: Дмитро Донцов – ідеолог українського інтегрального націоналізму, філософ, публіцист і громадський діяч, що ідейно сформував і загартував покоління національно свідомої української молоді, яка боролася зі зброєю в руках.
3 – Д: Василь Мудрий – голова Українського національно-демократичного об''єднання (УНДО) – найвпливовішої західноукраїнської парламентської партії, віцемаршалок сейму Польщі, головний редактор газети «Діло». Протягом 1921–1925 років був співзасновником і секретарем Львівського таємного українського університету, студенти й викладачі якого несли українську освітню ідею попри постійні заборони й переслідування з боку польської влади.
4 – А: Августин Волошин – політичний, культурний, освітній, релігійний діяч, Президент Карпатської України, державну незалежність якої було проголошено 15 березня 1939 року.
Правильна відповідь: 1 – Б, 2 – Г, 3 – Д, 4 – А.','[]','https://zno.osvita.ua/ukraine-history/670/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_his-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','390b726771648f8d0768b25f13c62608a6a54e9ff68078a8c46182da5f3e6fa7','1','official','matching',(SELECT id FROM topics WHERE subject_slug='history' AND name='Західноукраїнські землі в міжвоєнний період')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
