INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-history-s2-q26','34366','history','2025','2','26','ordering','Установіть послідовність подій національно-культурного життя кінця ХVIII – ХІХ ст.','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"видання в Будапешті альманаху «Русалка Дністровая»","images":[]},{"marker":"Б","text":"видання в Петербурзі перших трьох частин «Енеїди» Івана Котляревського","images":[]},{"marker":"В","text":"видання в Петербурзі першого українського журналу «Основа»","images":[]},{"marker":"Г","text":"перше видання в Петербурзі «Кобзаря» Тараса Шевченка","images":[]}]}]','1b;2a;3d;4c','Пояснення
 ТЕМА: Українські землі в складі Російської імперії наприкінці XVIII – у першій половині XIX ст. Українські землі у складі Австрійської імперії наприкінці XVIII – у першій половині XIX ст. Українські землі в складі Російської імперії в другій половині XIX ст.
Б 1798 р. – видання в Петербурзі перших трьох частин «Енеїди» Івана Котляревського
А 1837 р. – видання в Будапешті альманаху «Русалка Дністровая»
Г 1840 р. – перше видання в Петербурзі «Кобзаря» Тараса Шевченка
В 1861 р. – видання в Петербурзі першого українського журналу «Основа»
Правильна відповідь: Б, А, Г, В.','[]','https://zno.osvita.ua/ukraine-history/670/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_his-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','059c6051abaa2d3eec92f864e8ec8cea2afca8af5e4d8abc046fd7f59bf2f202','1','official','ordering',(SELECT id FROM topics WHERE subject_slug='history' AND name='Міжтематичні завдання з історії України')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
