INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-history-s2-q27','34367','history','2025','2','27','ordering','Установіть послідовність суспільно-політичних процесів та явищ, відображених на карикатурах.','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"","images":["/question-assets/history/34367-o1-1.png"]},{"marker":"Б","text":"","images":["/question-assets/history/34367-o2-1.png"]},{"marker":"В","text":"","images":["/question-assets/history/34367-o3-1.png"]},{"marker":"Г","text":"","images":["/question-assets/history/34367-o4-1.png"]}]}]','1c;2d;3a;4b','Пояснення
 ТЕМА: Україна в перші повоєнні роки. Україна в умовах десталінізації. Відновлення незалежності України. Становлення України як незалежної держави.
В Радянська карикатура присвячена політичній кампанії перших повоєнних років – «лисенківщині», яку супроводжувало цькуванням генетиків.
Наукові підходи, що суперечили марксистсько-ленінській ідеології, визнавали антинауковими. Ініціатор кампанії Трохим Лисенко відкидав так званий менделізм-морганізм: Грегор Мендель відкрив закони спадковості, Томас Морган одержав Нобелівську премію за відкриття, пов''язані з роллю хромосом у спадковості. Лисенко ж стверджував, що можна змінювати властивості рослин вирощуванням у специфічних умовах, і це відповідало грандіозним планам соціалістичного перетворення природи. «Лисенківщина» завдала значної шкоди радянській біології на роки вперед.
Г На карикатурі, створеної за часів відлиги висміяно нерозуміння окремими керівниками необхідності впровадження в сівозміну кукурудзи, яку вирішив зробити основною сільськогосподарською культурою Микита Хрущов.
А На карикатурі закцентовано проблему реалізації політики перебудови Михайла Горбачова, коли, виголошуючи перебудовні гасла, на ділі консервативні сили чинили опір реальним змінам.
Б На карикатурі відображено проблеми корупції в системі органів державної влади сучасної України.
Правильна відповідь: В, Г, А, Б.','[]','https://zno.osvita.ua/ukraine-history/670/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_his-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','694f46f21b4528bd169e50a7f555ee23b812f5a6a8f2999c932a4ea16ce8d958','1','official','ordering',(SELECT id FROM topics WHERE subject_slug='history' AND name='Міжтематичні завдання з історії України')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('history','Українські землі у складі Російської імперії в другій половині XIX ст.','Українські землі у складі імперій',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-history-s2-q28','34368','history','2025','2','28','multiple_choice','Позначте імена діячів українського професійного театру.','[{"title":"Варіанти відповіді","options":[{"marker":"1","text":"Марко Кропивницький","images":[]},{"marker":"2","text":"Володимир Симиренко","images":[]},{"marker":"3","text":"Микола Садовський","images":[]},{"marker":"4","text":"Іван Пулюй","images":[]},{"marker":"5","text":"Марія Заньковецька","images":[]},{"marker":"6","text":"Іван Труш","images":[]},{"marker":"7","text":"Дмитро Яворницький","images":[]}]}]','1;3;5','Пояснення
 ТЕМА: Українські землі в складі Російської імперії в другій половині XIX ст.
Марко Кропивницький в Єлисаветграді 1882 року збирає трупу під назвою «Товариство акторів» – із цього моменту розпочався розквіт професійного театру в Україні. До складу «театру корифеїв» входили брати Тобілевичі (псевдоніми: Іван Карпенко-Карий, Миколи Садовський, Панас Саксаганський), Михайло Старицький, Марія Заньковецька та інші.
Українським митцям у важких умовах XIX століття в Російській імперії вдалося обстояти власний голос, власну мову й посісти окреме місце в розмаїтті світового театру, збагативши його національною автентикою.
Правильна відповідь: 1, 3, 5.','[]','https://zno.osvita.ua/ukraine-history/670/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_his-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','78936115a8e0610b8bf9eab4127b6edab32e4b2862d482adfda65c594eb7d5df','1','official','multiple_choice',(SELECT id FROM topics WHERE subject_slug='history' AND name='Українські землі у складі Російської імперії в другій половині XIX ст.')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('history','Встановлення комуністичного тоталітарного режиму в Україні','Міжвоєнна доба і Друга світова війна',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-history-s2-q29','34369','history','2025','2','29','multiple_choice','Які з цитованих документів створено в період нової економічної політики (1921-1928 рр.)?','[{"title":"Варіанти відповіді","options":[{"marker":"1","text":"«..Усіх татар виселити з території Криму та поселити їх на постійне проживання в якості спейцпоселенців у районах Узбецької РСР...»","images":[]},{"marker":"2","text":"«.. вважати необхідним, передусім з політичних міркувань, виділення молдавського населення в спеціальну автономну республіку в складі УСРР...»","images":[]},{"marker":"3","text":"«...Робітничий клас України, у тому числі й російська його частина, аби керувати цим економічним неминучим процесом, повинен зрозуміти свої історичні завдання й оволодіти українською мовою...»","images":[]},{"marker":"4","text":"«..Я отримав диплом викладача грецької мови. Ураховуючи те, що всі грецькі школи припинили своє існування і навчання здійснювалося російською мовою, мені довелося змінити професію. Я пішов на завод...»","images":[]},{"marker":"5","text":"«Навчально-виховний процес у закладах освіти України є вільним від втручання політичних партій, громадських, релігійних організацій...»","images":[]},{"marker":"6","text":"«Оскільки Американська адміністрація допомоги (ARA) може вирішити за можливе та бажане надати негайно допомогу, особливо медичну, населенню України, то УСРР ...надасть [адміністрації] пільги...»","images":[]},{"marker":"7","text":"«Відповідно до Конституції УРСР державною мовою Української Радянської Соціалістичної Республіки є українська мова... Українська РСР створює необхідні умови для розвитку і використання мов інших національностей в республіці...»","images":[]}]}]','2;3;6','Пояснення
 ТЕМА: Встановлення комуністичного тоталітарного режиму в Україні. 
2. Наприкінці 1924 року, після ухвалення постанови ВУЦВК 12 жовтня, у складі УСРР було створено Автономну Молдавську Соціалістичну Радянську Республіку (АМСРР). До її складу ввійшли частини трьох округ тодішніх українських губерній: частина Балтської округи Одеської губернії, частина Одеської округи Одеської губернії, частина Тульчинської округи Подільської губернії. Це були райони на лівому березі Дністра, тобто територія сучасного Придністров’я та прилеглі українські землі. У такий спосіб більшовицьке керівництво намагалося радикалізувати прорадянські настрої в окупованій Румунією Бессарабії, а за наявності сприятливих умов – приєднати її. Згодом, 1940 року, після того, як СРСР забрав у Румунії Північну Буковину і Бессарабію, ця автономія не в повному складі відійшла до Молдавської РСР.
3. 1923 року Всеукраїнський Центральний Виконавчий Комітет і Рада народних комісарів Української Соціалістичної Радянської Республіки (УСРР) ухвалили декрет «Про заходи рівноправності мов і про допомогу розвиткові української мови». То був один з етапів політики коренізації, яка в радянській Україні набула форми українізації.
Радянська коренізація була насамперед засобом утвердження радянської влади.
6. Небачена посуха 1921 року й викачування продовольства в період запровадження продрозкладки виснажили запаси українців і призвели до катастрофічного становища на селі, особливо на півдні України.
Голод 1921–1923 років був чи не єдиним, який більшовики не заперечували, хоча його масштаби всіляко приховували від міжнародної спільноти, розповідаючи лише про продовольчі труднощі.
Міжнародна допомога, зокрема від Американської Адміністрації Допомоги (АRА), стабілізувала ситуацію, хоча в Україні її надходження було зорганізовано лише навесні 1922 р.
Правильна відповідь: 2, 3, 6.','[]','https://zno.osvita.ua/ukraine-history/670/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_his-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','4c37c323229dea840ffef7bcf98d3cc34c8150404ee27593140612ecd287b626','1','official','multiple_choice',(SELECT id FROM topics WHERE subject_slug='history' AND name='Встановлення комуністичного тоталітарного режиму в Україні')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('history','Творення нової України','Незалежна Україна',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-history-s2-q30','34370','history','2025','2','30','multiple_choice','Які судження щодо зображеного плаката, створеного в роки незалежності, є правильними?','[{"title":"Варіанти відповіді","options":[{"marker":"1","text":"Плакатстворено з нагоди заснування Збройних Сил України.","images":[]},{"marker":"2","text":"Плакат агітує брати участь у волонтерському русі.","images":[]},{"marker":"3","text":"Керівництво державою на момент створення плаката здійснював Л. Кучма.","images":[]},{"marker":"4","text":"Плакат рекламує товари широкого вжитку.","images":[]},{"marker":"5","text":"Плакат створений для стимулювання патріотичного піднесення.","images":[]},{"marker":"6","text":"Поява плаката зумовлена агресією Росії проти України.","images":[]},{"marker":"7","text":"Плакат пропагує роль держави в забезпеченні української армії якісною амуніцією.","images":[]}]}]','2;5;6','Пояснення
 ТЕМА: Творення нової України.
У лютому 2014 року розпочалася збройна агресія Росії проти України. Російська Федерація, порушуючи норми та принципи міжнародного права, двосторонні і багатосторонні угоди, анексувала Автономну Республіку Крим, окупувала окремі райони Донецької та Луганської областей.
З початком агресії небайдужі українці – волонтери – активно долучилися до допомоги армії. Везли усе, чого потребував фронт – від шкарпеток до тепловізорів. Саме волонтерська підтримка дала змогу армії твердо стати на ноги й боротися з ворогом.
Українське суспільство продемонструвало, що патріотизм є наріжним каменем у фундаменті держави, а національно-патріотичного виховання має бути пріоритетним напрямом державної політики.
Правильна відповідь: 2, 5, 6.','["/question-assets/history/34370-1.png"]','https://zno.osvita.ua/ukraine-history/670/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_his-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','0fff7b8f780e7235baaef0a1b490ac9a1c29b36724357cc859e282a5aa8cee9d','1','official','multiple_choice',(SELECT id FROM topics WHERE subject_slug='history' AND name='Творення нової України')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
