INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-biology-s1-q1','34652','biology','2025','1','1','single_choice','Французькі дослідник Люк Монтаньє і дослідниця Франсуаза Барре-Сінуссі отримали Нобелівську премію 2008 року за відкриття, які стали «однією з передумов розуміння біології СНІДу та способу його лікування».
Цей приклад ілюструє зв''язок біологічної науки з','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"фізикою","images":[]},{"marker":"Б","text":"екологією","images":[]},{"marker":"В","text":"медициною","images":[]},{"marker":"Г","text":"психологією","images":[]}]}]','c','Пояснення
 ТЕМА: Хімічний склад, структура і функціонування клітин. Реалізація спадкової інформації.
У завданні йдеться про відкриття, що вможливило розуміння причин і способу лікування СНІДу – вірусного захворювання, зокрема, людини, яке набуло ознак пандемії.
Отже, цей приклад ілюструє зв’язок біологічної науки із галуззю наукової та практичної діяльності, що вивчає нормальні та патологічні процеси в організмі людини, хвороби, методи їх діагностування, лікування та запобігання – медициною. 
Медицина — це галузь наукової та практичної діяльності, спрямована на збереження здоров''я, запобігання та лікування хвороб. Оскільки відкриття Монтаньє та Барре-Сінуссі стосується природи СНІДу та пошуку ліків проти нього, це прямий зв''язок біології з медициною.
Правильна відповідь – В.','[]','https://zno.osvita.ua/biology/681/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_bio-1.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','60dac7d826abfbfa971589f2bc4bd5db36dd9c5dd65b2a7e8aa8c1a3821881f7','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='biology' AND name='Хімічний склад клітини')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
