INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-biology-s1-q13','34664','biology','2025','1','13','single_choice','Профілактичним заходом щодо малярії є','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"кип''ятіння води перед уживанням","images":[]},{"marker":"Б","text":"вживання в їжу термічно обробленого м''яса","images":[]},{"marker":"В","text":"регулярні й дозовані фізичні навантаження","images":[]},{"marker":"Г","text":"контролювання популяцій тварин, в організмі яких мешкає збудник","images":[]}]}]','d','Пояснення
 ТЕМА: Біорізноманіття. Одноклітинні гетеротрофні еукаріотичні організми.
Малярія – інфекційне захворювання людини, спричинене малярійним плазмодієм. Цей одноклітинний паразитичний організм передається під час укусу малярійного комара, у крові якого він мешкає. Тому профілактичним заходом щодо малярії є контролювання популяції тварин, в організмі яких мешкає збудник.
Правильна відповідь – Г.','[]','https://zno.osvita.ua/biology/681/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_bio-1.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','4ac3a3406d749935f19bd595a7afce062139fb7ac7b8310263e7043a38143c57','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='biology' AND name='Структура еукаріотичної клітини')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
