INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-biology-s1-q14','34665','biology','2025','1','14','single_choice','Ознайомтеся з інформацією і виконайте завдання.
Вид Кораловий аспід звичайний (Micrurus corallinus) – хребетна тварина, яка мешкає в тропічних лісах Південної Америки. Трапляється на висоті до 500 м над рівнем моря. Харчується дрібними ящірками, охоче й часто п''є воду, але в неї не заходить. Є отруйною твариною. Шкіра вкрита лускою, у забарвленні характерне чергування широких червоних і вужчих чорних кілець, відокремлених одне від одного тонкими яскраво-зеленими смужками. Самиця відкладає в ґрунт до 10 яєць, з яких згодом з''являються схожі на дорослих нащадки.
У таблиці наведено систематичне положення описаної тварини, починаючи з найнижчого таксона.
Назву роду, до якого вона належить, позначено буквою','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"Кораловий аспід звичайний (Micrurus corallines)","images":[]},{"marker":"Б","text":"Кораловий аспід (Micrurus)","images":[]},{"marker":"В","text":"Аспідові (Elapidae)","images":[]},{"marker":"Г","text":"Лускаті (Squamata)","images":[]}]}]','b','Пояснення
 ТЕМА: Біорізноманіття. Справжні багатоклітинні тварини. Загальні ознаки будови й процесів життєдіяльності.
Щоб розв''язати завдання, треба проаналізувати наведену наукову інформацію. Розв’язання завдання потребує знань сучасних принципів наукової систематики організмів, розуміння принципів ієрархічності таксонів у систематиці та подвійних назв організмів.
В умові завдання зазначено видову назву тварини – Кораловий аспід звичайний. У таблиці наведено систематичне положення описаної тварини, починаючи з найнижчого таксона (виду) – Кораловий аспід звичайний (Micrurus corallinus). Отже, ця тварина належить до роду Кораловий аспід (Micrurus). 
Правильна відповідь – Б.','[]','https://zno.osvita.ua/biology/681/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_bio-1.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','c93b3a5701999f600ea51532c84bd33eeb592c3cc50efba5aaea5b9206a80e80','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='biology' AND name='Будова і життєдіяльність тварин')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
