INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-biology-s1-q30','34681','biology','2025','1','30','type_6','Чорнобильський радіаційно-екологічний біосферний заповідник став своєрідним притулком для багатьох тварин. Зображенням однієї з таких тварин прикрашено реверс пам''ятної монети. Ведмеді бурі повернулися на територію заповідника. Вони живляться різноманітною їжею, тож здатні адаптуватися до змін умов існування.
Позначте правильні закінчення тверджень','[{"title":"Зображена на монеті тварина належить до групи","options":[{"marker":"1","text":"хордові","images":[]},{"marker":"2","text":"молюски","images":[]},{"marker":"3","text":"членистоногі","images":[]}]},{"title":"В екосистемі зображена тварина є","options":[{"marker":"1","text":"продуцентом","images":[]},{"marker":"2","text":"консументом","images":[]},{"marker":"3","text":"редуцентом","images":[]}]},{"title":"За наведеною ознакою ведмедя бурого можна віднести до","options":[{"marker":"1","text":"стенобіонтних видів","images":[]},{"marker":"2","text":"еврибіонтних видів","images":[]},{"marker":"3","text":"видів із вузькимдіапазономвитривалості","images":[]}]}]','1;2;2','Пояснення
 ТЕМА: Основи екології та еволюційного вчення. Екологічні чинники. Популяція. Екосистеми.
В основі завдання наведено інформацію про мешкання на території Чорнобильського радіаційно-екологічного біосферного заповідника зображеної на монеті тварини. Ведмідь бурий є представником ссавців і належить до групи хордові.
В екосистемі ця тварина є складником функціональної групи консументів, адже є гетеротрофним організмом, який живиться різноманітною тваринною і рослинною їжею. За цією ознакою ведмедя бурого можна віднести до еврибіонтних видів, які мають широку екологічну нішу. 
Правильна відповідь: 122.','["/question-assets/biology/34681-1.png"]','https://zno.osvita.ua/biology/681/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_bio-1.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','f4b0996a165a7d9472e3d20315889a5e4b14b3930c1d74258d658964afee4735','1','official','type_6',(SELECT id FROM topics WHERE subject_slug='biology' AND name='Будова і життєдіяльність тварин')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('biology','Хімічний склад клітини','Клітина та реалізація спадкової інформації',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-biology-s2-q1','34682','biology','2025','2','1','single_choice','На початку ХVI ст. італійський науковець Лука Гіні винайшов спосіб зберігання рослин висушуванням їх між аркушами паперу – гербаризацію. Цей спосіб уможливив на той час розвиток','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"зоології","images":[]},{"marker":"Б","text":"ботаніки","images":[]},{"marker":"В","text":"генетики","images":[]},{"marker":"Г","text":"мікробіології","images":[]}]}]','b','Пояснення
 ТЕМА: Хімічний склад, структура і функціонування клітин. Реалізація спадкової інформації. 
У завданні йдеться про винайдення на початку XVI століття способу зберігання рослин висушуванням – гербаризацію.
Наука, об’єктом вивчення якої є рослини, – ботаніка. Отже, цей спосіб уможливив на той час розвиток ботаніки.
Правильна відповідь – Б.','[]','https://zno.osvita.ua/biology/682/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_bio-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','bcae15bdab601c86349551d9dcbf65b381eb980f240ffb4ff898970f5c60e7a4','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='biology' AND name='Хімічний склад клітини')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
