INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-biology-s2-q2','34683','biology','2025','2','2','single_choice','Яка сполука належить до вуглеводів?','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"соматотропін","images":[]},{"marker":"Б","text":"холестерол","images":[]},{"marker":"В","text":"целюлоза","images":[]},{"marker":"Г","text":"інсулін","images":[]}]}]','c','Пояснення
 ТЕМА: Хімічний склад, структура і функціонування клітин. Реалізація спадкової інформації. Хімічний склад клітини.
