INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-biology-s2-q27','34708','biology','2025','2','27','matching','Поєднайте поняття (1-4), яким характеризують поведінку тварин, з прикладом (А – Д), який ілюструє цю поведінку.','[{"title":"Варіанти відповіді","options":[{"marker":"1","text":"хомінг","images":[]},{"marker":"2","text":"грумінг","images":[]},{"marker":"3","text":"імпритинг","images":[]},{"marker":"4","text":"інстинкт","images":[]}]},{"title":"Варіанти відповіді","options":[{"marker":"А","text":"у собаки слиновиділення починається щойно вона побачить людину, яка завжди приносить їжу","images":[]},{"marker":"Б","text":"під час подорожі родиною з машини на автозаправці втік котик, через чотири доби він повернувся до свого дому","images":[]},{"marker":"В","text":"самиця шимпанзе перебирає шерсть свого маляти, знищує паразитів, чистить свою шерсть і шерсть інших особин родини","images":[]},{"marker":"Г","text":"каченята ходять за куркою, яка їх висиділа, уважаючи її своєю мамою","images":[]},{"marker":"Д","text":"під час жнив зайчиха, відчуваючи небезпеку, переносить своїх зайченят в інше місце","images":[]}]}]','1b;2c;3d;4e','Пояснення
 ТЕМА: Біорізноманіття. Поведінка тварин.
Хомінг – це здатність тварини повертатися до своєї ділянки проживання (гнізда, лігва) зі значної відстані.
Грумінг – соціальна поведінка тварин, що виражається в догляді за хутром, шкірою та пір''ям іншої особини.
Імпринтинг – форма навчання, яка характеризується фіксацією в пам''яті ознак об''єктів під час формування або корекції вроджених поведінкових реакцій.
Інстинкт – уроджена автоматична складна програма поведінки, яка властива певному виду організмів і не вимагає попереднього досвіду чи навчання для її прояву. Це природні реакції на певні стимули або подразники, що допомагають організму виживати, адаптуватися та розмножуватися в навколишньому середовищі. 
Правильна відповідь: 1 – Б; 2 – В; 3 – Г; 4 – Д.','[]','https://zno.osvita.ua/biology/682/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_bio-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','6b078ecf07038d91af1657f4fb3c6bd7e26edf2af6a326567c2a4242a93c1c91','1','official','matching',(SELECT id FROM topics WHERE subject_slug='biology' AND name='Поведінка й адаптації тварин')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('biology','Еволюційне вчення','Екологія та еволюція',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-biology-s2-q28','34709','biology','2025','2','28','matching','Узгодьте відділ травного тракту (1-4) з процесом (А – Д), який у ньому відбувається.','[{"title":"Варіанти відповіді","options":[{"marker":"1","text":"ротова порожнина","images":[]},{"marker":"2","text":"шлунок","images":[]},{"marker":"3","text":"тонкий кишечник","images":[]},{"marker":"4","text":"товстий кишечник","images":[]}]},{"title":"Варіанти відповіді","options":[{"marker":"А","text":"бактерицидна дія лізоциму на їжу","images":[]},{"marker":"Б","text":"вироблення білкових гормонів – інсуліну й глюкагону","images":[]},{"marker":"В","text":"остаточне всмоктування води й мінеральних солей","images":[]},{"marker":"Г","text":"остаточне розщеплення білків до амінокислот","images":[]},{"marker":"Д","text":"початок розщеплення білків до пептидів","images":[]}]}]','1a;2e;3d;4c','Пояснення
 ТЕМА: Організм людини як біологічна система.
У ротовій порожнині відбувається бактерицидна (знезаражувальна) дія лізоциму на їжу, а в шлунку – початок розщеплення білків до пептидів. Тонкий кишківник забезпечує остаточне розщеплення білків до амінокислот, а в товстому кишківнику відбувається остаточне всмоктування води й мінеральних солей. Вироблення білкових гормонів інсуліну й глюкагону відбувається в підшлунковій залозі (залоза змішаної секреції), якої немає в переліку органів.
Правильна відповідь: 1 – А; 2 – Д; 3 – Г; 4 – В.','[]','https://zno.osvita.ua/biology/682/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_bio-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','4c356641fb0682b70bfb129a9627ec678ab6a41c1da1fb22ebf528d550577e52','1','official','matching',(SELECT id FROM topics WHERE subject_slug='biology' AND name='Еволюційне вчення')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('biology','Мінливість організмів','Спадковість і мінливість',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-biology-s2-q29','34710','biology','2025','2','29','type_6','Дослідники схрестили гомозиготні рослини із червоним і білим забарвленням пелюсток. Поміж нащадків у другому поколінні гібридів нарахували 47 рослин із червоними квітками й 16 – з білими. Надалі рослину із червоними квітками (гібрид другого покоління) схрестили з батьківською формою, що мала білі квітки. З-поміж нащадків цього схрещування нарахували 38 рослин із червоними квітками й 36 – з білими. Проаналізуйте результати описаного дослідження і визначте правильні твердження.','[{"title":"Співвідношення генотипів у другому поколінні –","options":[{"marker":"1","text":"3:1","images":[]},{"marker":"2","text":"1:2:1","images":[]},{"marker":"3","text":"9:3:3:1","images":[]}]},{"title":"Гібрид \\(\\mathrm{F_2}\\) схрещений із рослиною, яка має білі квітки, був","options":[{"marker":"1","text":"гомозиготним за домінантною ознакою","images":[]},{"marker":"2","text":"гомозиготним за рецесивною ознакою","images":[]},{"marker":"3","text":"гетерозиготним","images":[]}]},{"title":"Описане схрещування гібрида другого покоління (із червоним забарвленням квіток) із білоквітковою батьківською рослиною є прикладом схрещування","options":[{"marker":"1","text":"дигібридного","images":[]},{"marker":"2","text":"полігібридного","images":[]},{"marker":"3","text":"аналізувального","images":[]}]}]','2;3;3','Пояснення
 ТЕМА: Основи спадковості та мінливості організмів. Основи спадковості.
У завданні описано розщеплення за фенотипом – 3 : 1. Таке розщеплення є виявом закону розщеплення ознак у другому поколінні (другий закон Менделя). Отже, співвідношення генотипів у другому покоління – 1 : 2 : 1. Під час подальшого схрещування рослини із червоними квітками (гібрид другого покоління) з батьківською формою, що мала білі квітки (гомозиготна форма за рецесивною ознакою), отримали співвідношення за фенотипом 1 : 1 (38 рослин із червоними квітками й 36 рослин із білими квітками.
Отже, гібрид F2 був гетерозиготним. Описане схрещування гібридів другого покоління (із червоним забарвленням квіток) із білоквітковою батьківською рослиною (чиста гомозиготна лінія) є прикладом аналізувального схрещування.
Правильна відповідь: 233.','[]','https://zno.osvita.ua/biology/682/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_bio-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','04e806a85e9975952b4f856ae291c7acaa3568706a89cc8a9ffe3b44658ded5b','1','official','type_6',(SELECT id FROM topics WHERE subject_slug='biology' AND name='Мінливість організмів')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('biology','Екосистеми й ланцюги живлення','Екологія та еволюція',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-biology-s2-q30','34711','biology','2025','2','30','type_6','Проаналізуйте зображену трофічну сітку. Визначте правильні твердження щодо неї.','[{"title":"Поміж зображених організмів є","options":[{"marker":"1","text":"редуценти","images":[]},{"marker":"2","text":"детритофаги","images":[]},{"marker":"3","text":"консументи","images":[]}]},{"title":"Організм, який у наведених ланцюгах живлення перебуває на третьому або четвертому трофічному рівні, позначено буквою","options":[{"marker":"1","text":"А","images":[]},{"marker":"2","text":"Б","images":[]},{"marker":"3","text":"В","images":[]}]},{"title":"Рослиноїдну тварину позначено буквою","options":[{"marker":"1","text":"А","images":[]},{"marker":"2","text":"Б","images":[]},{"marker":"3","text":"В","images":[]}]}]','3;1;3','Пояснення
 ТЕМА: Основи екології та еволюційного вчення. Екосистеми.
Основа завдання містить схему трофічної сітки. Треба визначити правильні твердження щодо неї. Поміж зображених організмів є консументи – гетеротрофні тваринні організми, які живляться тваринною і рослинною їжею.
Організм, який у наведених ланцюгах живлення перебуває на третьому або четвертому трофічному рівні – хижий птах, якого позначено буквою А. Він може живитися і рослиноїдними тваринами (організми другого трофічного рівня), і хижими тваринами (організми третього трофічного рівня). Рослиноїдну тварину (коник) позначено буквою В.
Правильна відповідь: 313.','["/question-assets/biology/34711-1.png"]','https://zno.osvita.ua/biology/682/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_bio-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','cd894e7b1af136586b2f2b0fb3068b1434db3681a9120fbd99a4e5b77512bf27','1','official','type_6',(SELECT id FROM topics WHERE subject_slug='biology' AND name='Екосистеми й ланцюги живлення')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('geography','Форма, рухи й розміри Землі','Загальна географія',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-geography-s1-q1','34896','geography','2025','1','1','single_choice','Яке значення першої навколосвітньої подорожі під керівництвом Фернана Магеллана?','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"створено першу географічну карту світу","images":[]},{"marker":"Б","text":"визначено площі суходолу й Океану","images":[]},{"marker":"В","text":"винайдено умовну фігуру Землі – геоїд","images":[]},{"marker":"Г","text":"доведено, що Земля має форму кулі","images":[]}]}]','d','Пояснення
 ТЕМА: Форма і розміри Землі.
Перша в історії навколосвітня подорож під керівництвом Фернана Магеллана почалася лише тому, що Земля куляста. Саме тоді було сформовано уявлення про розміри планети, а також визначено те, що Світовий океан – це неперервний водний простір.
Правильна відповідь: Г.','["/question-assets/geography/34896-1.png"]','https://zno.osvita.ua/geography/689/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_geo-1.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','7869035dffd00fd76a967c146ae6c785c9bb5d4676fce20e4f8416569d9617f1','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='geography' AND name='Форма, рухи й розміри Землі')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('geography','Біосфера та географічна оболонка','Загальна географія',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-geography-s1-q2','34897','geography','2025','1','2','single_choice','Про яку закономірність географічної оболонки йдеться в тексті рекламного флаєра?','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"цілісність","images":[]},{"marker":"Б","text":"ритмічність","images":[]},{"marker":"В","text":"зональність","images":[]},{"marker":"Г","text":"безперервність","images":[]}]}]','b','Пояснення
 ТЕМА: Географічна оболонка.
Періодичну повторюваність певних процесів у географічній оболонці називають ритмічністю. Розрізняють добові та сезонні ритми. Зміна дня і ночі («після темряви настає світанок») відбувається внаслідок обертання Землі навколо власної осі. Сезонні ж ритми («після зими обов’язково приходить весна») відбуваються внаслідок того, що наша планета рухається орбітою навколо Сонця.
Правильна відповідь: Б.','["/question-assets/geography/34897-1.png"]','https://zno.osvita.ua/geography/689/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_geo-1.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','8f59ed2d677f00e1c5d875f7e171a5c850ea8f941a1383effcd0a58e7db41703','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='geography' AND name='Біосфера та географічна оболонка')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('geography','Гідросфера','Загальна географія',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-geography-s1-q3','34898','geography','2025','1','3','single_choice','Енергія припливів і відпливів є складником ресурсного потенціалу','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"літосфери","images":[]},{"marker":"Б","text":"атмосфери","images":[]},{"marker":"В","text":"гідросфери","images":[]},{"marker":"Г","text":"біосфери","images":[]}]}]','c','Пояснення
 ТЕМА: Ресурсний потенціал гідросфери.
Природні ресурси – це тіла й сили природи, які за певного рівня розвитку технологій використовують або можуть бути використані для задоволення потреб людства. У морських припливах і відпливах приховано енергію, яку можна перетворити на електричну.
Правильна відповідь: В.','[]','https://zno.osvita.ua/geography/689/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_geo-1.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','09a5499d88ebfc0d95708e78541baf7dba17289e8a487d845b8c6a76a81ce146','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='geography' AND name='Гідросфера')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('geography','Урбанізація','Населення України та світу',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-geography-s1-q4','34899','geography','2025','1','4','single_choice','Париж і Лондон –','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"світові (глобальні) міста","images":[]},{"marker":"Б","text":"монофункціональні міста","images":[]},{"marker":"В","text":"міста одного мегалополісу","images":[]},{"marker":"Г","text":"поліцентричні агломерації","images":[]}]}]','a','Пояснення
 ТЕМА: Населення України та світу. Урбанізація.
Світове місто – це важливий центр світової економіки, політики та культури, який сильно впливає на ключові регіони світу. Такі міста є поліфункціональними, як-от Париж і Лондон. Разом із приміськими зонами вони утворюють моноцентричні агломерації – Лондонську і Паризьку та не належать до одного мегалополісу.
Правильна відповідь: А.','[]','https://zno.osvita.ua/geography/689/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_geo-1.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','8254ce3c82b1e5118607682462950ee6b4192a4017c4217c4a76d29207f79bf4','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='geography' AND name='Урбанізація')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('geography','Політична карта світу','Регіони та країни',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-geography-s1-q5','34900','geography','2025','1','5','single_choice','Відомий економіст Джеффрі Сакс стверджував, що країни, які не мають виходу до моря, ніколи не досягнуть високого рівня економічного розвитку. Географи для спростування цієї думки наводять приклад','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"Китаю","images":[]},{"marker":"Б","text":"Казахстану","images":[]},{"marker":"В","text":"Німеччини","images":[]},{"marker":"Г","text":"Швейцарії","images":[]}]}]','d','Пояснення
 ТЕМА: Типізація країн світу за рівнем економічного розвитку.
Географічне положення істотно впливає на розвиток країн. За цим критерієм виокремлюють приморські держави, які мають вихід до моря. Це надає їм важливі переваги: змогу підтримувати економічні зв’язки з іншими країнами світу, доступ до Світового океану та його ресурсів. Водночас деякі приморські країни залишаються бідними, оскільки не змогли використати ці переваги для розвитку торгівлі, економіки чи флоту. Натомість є внутрішньоконтинентальні держави, що не мають виходу до моря, але досягли високого рівня економічного розвитку, як-от Швейцарія.
Правильна відповідь: Г.','[]','https://zno.osvita.ua/geography/689/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_geo-1.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','4acf556491d05b36b2725db7dc5ad7377e9379c0a449d4bfc493626d4f092108','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='geography' AND name='Політична карта світу')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('geography','Літосфера і рельєф','Загальна географія',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-geography-s1-q6','34901','geography','2025','1','6','single_choice','Проаналізуйте розташування Австралії на картосхемі літосферних плит.
Наслідком такого розташування материка відносно меж літосферних плит є','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"сповільнене вивітрювання","images":[]},{"marker":"Б","text":"активне горотворення","images":[]},{"marker":"В","text":"низька сейсмічність","images":[]},{"marker":"Г","text":"інтенсивний карст","images":[]}]}]','c','Пояснення
 ТЕМА: Географія материків і океанів: сучасні тектонічні процеси Австралії.
Австралія лежить у центральній частині Індо-Австралійської літосферної плити, де немає глибинних розломів. Через віддаленість від меж (країв) літосферних плит на материку немає активних вулканів і не стаються сильні землетруси.
Правильна відповідь: В.','["/question-assets/geography/34901-1.jpeg"]','https://zno.osvita.ua/geography/689/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_geo-1.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','cce83380d869009a9bfaaa3ba195d67c67a5e3a537ba71e60d771612e35fa564','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='geography' AND name='Літосфера і рельєф')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('geography','Топографічна карта','Загальна географія',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-geography-s1-q7','34902','geography','2025','1','7','single_choice','Австралія – найнижчий (середня абсолютна висота 330 м) і найпласкіший континент планети.
Позначте тектонічні структури (див. карти), домінування яких зумовило таку особливість рельєфу материка.','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"щити з тектонічними розломами","images":[]},{"marker":"Б","text":"давня і молоді платформи","images":[]},{"marker":"В","text":"області альпійської складчастості","images":[]},{"marker":"Г","text":"області герцинської складчастості","images":[]}]}]','b','Пояснення
 ТЕМА: Географія материків і океанів: тектонічна будова, рельєф Австралії.
Розгляньмо тектонічну карту Австралії та прочитаємо легенду. На заході, частково на півночі й у центральній частині материка виходять на поверхню кристалічні щити давньої (докембрійської) платформи. Східну, північну й частково центральну частину материка вкриває осадовий чохол давніх і молодих платформ. Оскільки в основі материка лежить давня платформа, то в рельєфі переважають рівнини.
Правильна відповідь: Б.','["/question-assets/geography/34902-1.jpeg"]','https://zno.osvita.ua/geography/689/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_geo-1.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','f2ec6ecbfa793e207b12c20dd22d876ca3e5e962810fae615e19b38e2fe563c9','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='geography' AND name='Топографічна карта')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('geography','Літосфера і рельєф','Загальна географія',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-geography-s1-q8','34903','geography','2025','1','8','single_choice','Могутня скеля Аєрс-Рок (див. рисунок) здіймається над рівниною на 350 м, проте основна її частина – під землею. Скеля сформована геологічними процесами приблизно 680 млн років тому, складена червоним піщаником і вкрита паралельними борознами глибиною до 2 м.
Визначте походження скелі.','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"грабен між двома горстами","images":[]},{"marker":"Б","text":"залишок давнього коралового рифу","images":[]},{"marker":"В","text":"кратер у конусі згаслого вулкана","images":[]},{"marker":"Г","text":"останець як результат ерозії","images":[]}]}]','d','Пояснення
 ТЕМА: Географія материків і океанів: рельєф Австралії.
Сучасного вигляду скеля Аєрс-Рок набула внаслідок довготривалих процесів вивітрювання й ерозії. Вітер, різкі коливання температур, періодичні опади поступово руйнували піщаник, утворюючи, зокрема, глибокі паралельні борозни завглибшки до 2 метрів. Подібні ізольовані форми земної поверхні називають останцями.
Правильна відповідь: Г.','["/question-assets/geography/34903-1.png"]','https://zno.osvita.ua/geography/689/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_geo-1.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','7b7b0e8550554a483c7eb615752222a94e782212c9e43d9884de9af3d288a858','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='geography' AND name='Літосфера і рельєф')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('geography','Природні комплекси й ландшафти','Фізична географія України',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-geography-s1-q9','34904','geography','2025','1','9','single_choice','Ідентифікуйте природну зону за поетичним описом типового для неї краєвиду:
«Шумить верхами буйний ліс – 
Дуби, берези, буки.
Співає сойка, свище дрізд
І воркотять голубки...»
Визначте розташування цієї природної зони на картосхемі України.','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"Природна зона А","images":[]},{"marker":"Б","text":"Природна зона Б","images":[]},{"marker":"В","text":"Природна зона В","images":[]},{"marker":"Г","text":"Природна зона Г","images":[]}]}]','b','Пояснення
 ТЕМА: Природні комплекси (ландшафти) України.
Звернімо увагу на лісову рослинність: дуб, береза, бук. Такі деревні породи характерні для природної зони широколистих лісів, яка локалізується на заході України та не має такого ж широтного простягання, як зона мішаних лісів.
Правильна відповідь: Б.','["/question-assets/geography/34904-1.jpeg"]','https://zno.osvita.ua/geography/689/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_geo-1.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','89256a95773ad1bc15badd7b8ffb3978dae211f0378a07b6710e0315a31a4efb','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='geography' AND name='Природні комплекси й ландшафти')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('geography','Атмосфера і клімат','Загальна географія',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-geography-s1-q10','34905','geography','2025','1','10','single_choice','Позначте природну зону, де під багаторічною трав''янистою рослинністю за періодичного зволоження в умовах помірного теплого клімату на пухких карбонатних породах (переважно лесах) сформувалися найродючіші ґрунти – чорноземи типові.','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"Природна зона А","images":[]},{"marker":"Б","text":"Природна зона Б","images":[]},{"marker":"В","text":"Природна зона В","images":[]},{"marker":"Г","text":"Природна зона Г","images":[]}]}]','c','Пояснення
 ТЕМА: Природні комплекси (ландшафти) України.
З високою імовірністю визначити тип ґрунту на цілинній ділянці дає змогу природна рослинність. У лісостеповій зоні під багаторічною трав’янистою рослинністю в умовах періодичного зволоження формуються чорноземи типові – найродючіші ґрунти помірного поясу.
Правильна відповідь: В.','["/question-assets/geography/34905-1.jpeg"]','https://zno.osvita.ua/geography/689/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_geo-1.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','75101088fd8679821f5a5cf1244919e81fcce5017debb3d3b31d6cfca1523ab0','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='geography' AND name='Атмосфера і клімат')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('geography','Природні комплекси й ландшафти','Фізична географія України',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-geography-s1-q11','34906','geography','2025','1','11','single_choice','На карті відображено таку закономірність:
«На півночі й заході України більша, ніж на півдні й сході, частка (%)...','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"вічнозелених твердолистих лісів»","images":[]},{"marker":"Б","text":"полезахисних лісових насаджень»","images":[]},{"marker":"В","text":"лісів у загальній площі земель»","images":[]},{"marker":"Г","text":"широколистих дерев у лісах»","images":[]}]}]','c','Пояснення
 ТЕМА: Природні комплекси (ландшафти) України.
Вічнозелені твердолисті ліси – це природна зона, характерна для субтропічного кліматичного поясу. В Україні ці ліси трапляються подекуди на Південному березі Криму.
Полезахисні лісові насадження облаштовують у степовій і лісостеповій природних зонах для запобігання ерозійним процесам і збереження родючості ґрунтів.
Ліси на території України розміщені нерівномірно: вони сконцентровані переважно на Поліссі та в Українських Карпатах. Тому на півночі й заході більша частка лісів у загальній площі земель, ніж на півдні та сході.
Широколисті ліси України різняться за видовим складом на різних територіях, однак найбільші площі їх зосереджені в західній частині країни.
Правильна відповідь: В.','["/question-assets/geography/34906-1.png"]','https://zno.osvita.ua/geography/689/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_geo-1.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','3819d3a0384c27ed8822cfebc264aeb11d05a58a93173c26019373953861899e','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='geography' AND name='Природні комплекси й ландшафти')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('geography','Розселення і густота населення','Населення України та світу',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-geography-s1-q12','34907','geography','2025','1','12','single_choice','На діаграмах відображено частки міського населення у світі 2025 р. і 2050 р. (за прогнозом ООН).
У прогнозі ООН йдеться про збільшення','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"кількості населення","images":[]},{"marker":"Б","text":"рівня урбанізації","images":[]},{"marker":"В","text":"темпу депопуляції","images":[]},{"marker":"Г","text":"природного приросту","images":[]}]}]','b','Пояснення
 ТЕМА: Населення України та світу: розселення населення.
Збільшення частки міського населення, поширення міського способу життя та зростання ролі міст називають урбанізацією. Тому в прогнозі ООН йдеться про збільшення рівня урбанізації.
Загальна кількість населення охоплює і міських, і сільських жителів.
Природний рух населення є найважливішим чинником зміни кількості й складу населення окремих країн або регіонів світу. Його характеризує показник природного приросту, який може бути додатним або від’ємним. У разі зменшення чисельності населення спостерігають явище депопуляції.
Правильна відповідь: Б.','["/question-assets/geography/34907-1.png"]','https://zno.osvita.ua/geography/689/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_geo-1.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','9c1ac236c2ba3bb08b0ae6aabe4da6c6ae851ed79beb982185ab8b3b66c1c8b8','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='geography' AND name='Розселення і густота населення')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('geography','Природа Євразії','Материки та океани',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-geography-s1-q13','34908','geography','2025','1','13','single_choice','У таблиці наведено результати порівняльного аналізу світових і європейських тенденцій у розселенні населення від 1950 до 2020 р. Зміна якого показника в Україні відповідає світовій і європейській тенденції?
 Показник
 Світ
 Європа
 Україна
 А
 Загальна чисельність населення
 збільшення
 збільшення
 ?
 Б
 Середня густота населення
 збільшення
 збільшення
 ?
 В
 Частка міського населення
 збільшення
 збільшення
 ?
 Г
 Кількість міст-мільйонників
 збільшення
 збільшення
 ?','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"Загальна чисельність населення","images":[]},{"marker":"Б","text":"Середня густота населення","images":[]},{"marker":"В","text":"Частка міського населення","images":[]},{"marker":"Г","text":"Кількість міст-мільйонників","images":[]}]}]','c','Пояснення
 ТЕМА: Населення України та світу: розселення населення.
З 1993 року чисельність населення в Україні зменшується внаслідок різних соціально-економічних чинників.
Показники народжуваності залишаються нижчими за показники смертності, тому в країні спостерігають від’ємний природний приріст населення – депопуляцію. Через системну демографічну кризу зменшується густота населення в країні. Станом на 2020 рік в Україні залишалося три міста-мільйонники – Київ, Харків і Одеса. Із цього списку вибули Дніпро й Донецьк.
А от збільшення частки міського населення відповідає світовим і європейським тенденціям. Для України характерні високий рівень урбанізації, хоч і низькі темпи її зростання.
Правильна відповідь: В.','[]','https://zno.osvita.ua/geography/689/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_geo-1.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','5613b2ca267e9bf1374b5e20a632289e0a5a4d42a4883e00e12c2381c90b547c','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='geography' AND name='Природа Євразії')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('geography','Розселення і густота населення','Населення України та світу',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-geography-s1-q14','34909','geography','2025','1','14','single_choice','У якій із позначених на карті країн проживає 12 % міського населення світу, а частка містян становить лише 35 % від усіх її жителів?','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"Країна А","images":[]},{"marker":"Б","text":"Країна Б","images":[]},{"marker":"В","text":"Країна В","images":[]},{"marker":"Г","text":"Країна Г","images":[]}]}]','b','Пояснення
 ТЕМА: Населення України та світу: розселення населення.
На картосхемі позначено А – Канаду, Б – Індію, В – Бразилію, Г – ПАР.
Рівень урбанізації в Канаді, Бразилії та ПАР є значно вищим: у Канаді та Бразилії понад 80 %, а в ПАР – понад 2/3 населення є міськими жителями.
В Індії ж переважає сільське населення, а рівень урбанізації залишається відносно невисоким – приблизно 35 %. Станом на 2025 рік Індія є найбільш населеною країною світу, тому, попри невисоку частку містян у межах країни, на них припадає приблизно 12 % усього міського населення планети.
Правильна відповідь: Б.','["/question-assets/geography/34909-1.png"]','https://zno.osvita.ua/geography/689/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_geo-1.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','c05ca73f0403ee7918b54fb0bb2eb42892cd9a7debd9f22a6ae273cb1ee17731','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='geography' AND name='Розселення і густота населення')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('geography','Первинний сектор','Україна і світове господарство',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-geography-s1-q15','34910','geography','2025','1','15','single_choice','За яким критерієм можна визначити, що на картограмі відображено обсяги вирощеного цукрового буряку в областях України?','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"спеціалізація найгустіше заселених районів","images":[]},{"marker":"Б","text":"вирощування вздовж зрошувальних каналів","images":[]},{"marker":"В","text":"зосередження в субтропічних широтах","images":[]},{"marker":"Г","text":"концентрування в лісостеповій зоні","images":[]}]}]','d','Пояснення
 ТЕМА: Первинний сектор економіки: сільське господарство. 
Найбільші обсяги вирощування цукрового буряку спостерігають у Вінницькій і Полтавській областях. Це не випадково: культуру зосереджено переважно в межах сільськогосподарської зони Лісостепу, де поширені сірі лісові ґрунти й чорноземи типові, а також оптимальний баланс тепла й вологи.
Правильна відповідь: Г.','["/question-assets/geography/34910-1.jpeg"]','https://zno.osvita.ua/geography/689/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_geo-1.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','2351afe500690a1264d60a00a66a2c7009a1541ded2107c74959cb0791b2ba09','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='geography' AND name='Первинний сектор')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('geography','Харчова та легка промисловість','Україна і світове господарство',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-geography-s1-q16','34911','geography','2025','1','16','single_choice','Проаналізуйте розташування (див. карту) Крижопільського цукрового заводу (селище Городківка, Вінницька обл.). Який основний чинник зумовив його розміщення?','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"природноресурсний","images":[]},{"marker":"Б","text":"споживчий","images":[]},{"marker":"В","text":"сировинний","images":[]},{"marker":"Г","text":"транспортний","images":[]}]}]','c','Пояснення
 ТЕМА: Вторинний сектор економіки: харчова промисловість.
Для виробництва 1 тонни цукру потрібно 7 тонн цукрових буряків. Тому цукровий завод розташовують так, щоб навколо були агрофірми й фермери, які є постачальниками сировини (буряків). Сировинний чинник зумовлює розташування тих виробництв, де на одиницю готової продукції треба використати в кілька разів більше витратних матеріалів.
Природноресурсний чинник зумовлює розташування тих підприємств, які освоюють родовища корисних копалин, заготовляють деревину.
Споживчий чинник найбільше впливає на розташування виробництв, продукція яких забезпечує повсякденні потреби й швидко псується.
Транспортний чинник визначає доступність і вартість перевезень сировини, матеріалів, готової продукції.
Правильна відповідь: В.','["/question-assets/geography/34911-1.jpeg"]','https://zno.osvita.ua/geography/689/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_geo-1.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','f87c1691592e283756ebed4a02ffbb5241960f72d0d39df1cd66f289f4b4ee6a','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='geography' AND name='Харчова та легка промисловість')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('geography','Національна та світова економіка','Україна і світове господарство',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-geography-s1-q17','34912','geography','2025','1','17','single_choice','Прочитайте прогноз аналітика ринку цукру в Україні: «Цукор – це soft commodities, для якого найважливіший критерій – собівартість. Залишаться лише найефективніші цукрові заводи з енергозберігаючими технологіями, оптимізованою кількістю персоналу та найвищою якістю виробленого цукру. На ринку з 30 заводів, які нині працюють, залишиться 18-20, але потужніших».
Про яку форму суспільної організації виробництва цукру в Україні йдеться в прогнозі?','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"спеціалізацію","images":[]},{"marker":"Б","text":"кооперування","images":[]},{"marker":"В","text":"концентрацію","images":[]},{"marker":"Г","text":"комбінування","images":[]}]}]','c','Пояснення
 ТЕМА: Національна економіка: форми суспільної організації виробництва.
Зосередження виробництва на великих підприємствах – це концентрація. Наслідком виробничої концентрації є формування гігантських підприємств із великою територією, і десятками тисяч працівників (на ринку з 30 заводів, які нині працюють, залишиться 18–20, але потужніших).
Спеціалізація – це орієнтація виробника на виготовлення певної групи товарів чи послуг.
Кооперування виробництва — процес установлення виробничих зв’язків між різними спеціалізованими підприємствами, які спільно працюють над виробництвом складної продукції.
Комбінуванням називають таку форму суспільної організації виробництва, за якої на одному підприємстві зосереджують виробництва різних видів продукції.
Правильна відповідь: В.','[]','https://zno.osvita.ua/geography/689/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_geo-1.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','fd98a0fde58b5ca5c23e721dcf97ac520533c7066371d923523a7dd2425cb7e5','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='geography' AND name='Національна та світова економіка')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('geography','Океани світу','Материки та океани',999);
INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-geography-s1-q18','34913','geography','2025','1','18','single_choice','У таблиці наведено інформацію щодо частки (%) регіонів у світовому виробництві фармацевтичної продукції у 2004 і 2023 рр. промисловості
