INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-geography-s2-q12','34937','geography','2025','2','12','single_choice','Проаналізуйте наведену в таблиці інформацію й оцініть демографічну ситуацію в умовній країні.
 Показники
 2024 р.
 Чисельність населення, тис. осіб
 6700
 Народжуваність, %
 10,5
 Смертність, %
 8,5
 Еміграція, тис. осіб
 30,1
 Імміграція, тис. осіб
 49,1','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"депопуляція населення","images":[]},{"marker":"Б","text":"старіння населення","images":[]},{"marker":"В","text":"розширене відтворення","images":[]},{"marker":"Г","text":"звужене відтворення","images":[]}]}]','c','Пояснення
 ТЕМА: Населення України та світу: демографічні процеси.
Депопуляцію спостерігають тоді, коли смертність перевищує народжуваність. У такому разі відбувається не приріст, а зменшення кількості населення. За даними таблиці народжуваність (10,5 ‰) перевищує смертність (8,5 ‰), отже, депопуляції немає.
Старіння населення – це процес збільшення частки літніх людей і зменшення частки дітей. Старінню населення властиві низький рівень народжуваності, уповільнення природного приросту та зростанням тривалості життя. У таблиці немає показників щодо вікового складу, тому оцінити старіння населення неможливо.
Для розширеного типу відтворення характерні високі показники народжуваності, стабільні показники смертності та додатний природний приріст, про що свідчать дані таблиці (варіант відповіді В).
Звужене відтворення населення характерне для країн із низькою народжуваністю й невисоким або від’ємним природним приростом.
Правильна відповідь: В.','[]','https://zno.osvita.ua/geography/690/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_geo-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','e7055e2c4f6d5d2f534bc3f9eb738212332ae5204d496062ff76eeda307901fa','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='geography' AND name='Міграції')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
