INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-geography-s2-q13','34938','geography','2025','2','13','single_choice','За даними таблиці визначте хід обчислення природного приросту населення (тис. осіб) в умовній країні за 2024 р.
 Показники
 2024 р.
 Чисельність населення, тис. осіб
 6700
 Народжуваність, %
 10,5
 Смертність, %
 8,5
 Еміграція, тис. осіб
 30,1
 Імміграція, тис. осіб
 49,1','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"\\(49\\mathord{,}1-30\\mathord{,}1=19\\mathord{,}0\\)","images":[]},{"marker":"Б","text":"\\((0\\mathord{,}0105-0\\mathord{,}0085)\\cdot 6700=13\\mathord{,}4\\)","images":[]},{"marker":"В","text":"\\(0\\mathord{,}0105\\cdot 6700-8\\mathord{,}5=61\\mathord{,}85\\)","images":[]},{"marker":"Г","text":"\\((10\\mathord{,}5+49\\mathord{,}1)\\cdot 6\\mathord{,}7=339\\mathord{,}5\\)","images":[]}]}]','b','Пояснення
 ТЕМА: Населення України та світу: демографічні процеси.
Різниця між кількістю народжених і кількістю померлих за певний період називають природним приростом. Він може бути додатним у разі перевищення народжуваності над смертністю, нульовим, коли ці показники мають однакове значення, і від’ємним, коли смертність більша від народжуваності. У такому разі відбувається не приріст, а зменшення кількості населення – депопуляція.
Чисельність населення (ЗКН): 6700 тис. осіб.
Коефіцієнт народжуваності (КН) = 10,5 ‰ = 0,0105.
Коефіцієнт смертності (КС) = 8,5 ‰ = 0,0085.
Формула природного приросту (ПП):
;
ПП = (0,0105 − 0,0085) × 6700;
ПП = 13,4 тис. осіб.
Правильна відповідь: Б.','[]','https://zno.osvita.ua/geography/690/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_geo-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','95bbad13c4abf9601e41985bc3fdcebe5173248bb2bbe58ad8753888e0e99300','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='geography' AND name='Міграції')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
INSERT OR IGNORE INTO topics(subject_slug,name,section_name,position) VALUES('geography','Міграції','Населення України та світу',999);
