INSERT INTO questions(id,external_id,subject_slug,year,session,position,question_type,prompt,options_json,correct_answer,explanation,images_json,source_url,official_pdf_url,attribution,canonical_key,active,source_kind,exam_format,topic_id) VALUES('nmt2025-geography-s2-q16','34941','geography','2025','2','16','single_choice','Публічне акціонерне товариство «АрселорМіттал Кривий Ріг» – лідер гірничо-металургійного комплексу України, підприємство з повним металургійним циклом. Ефективну діяльність компанії зумовлено передусім','[{"title":"Варіанти відповіді","options":[{"marker":"А","text":"прикордонним розташуванням виробництва","images":[]},{"marker":"Б","text":"комплексним переробленням сировини","images":[]},{"marker":"В","text":"власним видобутком коксівного вугілля","images":[]},{"marker":"Г","text":"наявністю джерела дешевої гідроелектроенергії","images":[]}]}]','b','Пояснення
 ТЕМА: Вторинний сектор економіки: металургійне виробництво в Україні.
ПАТ «АрселорМіттал Кривий Ріг» – металургійний комбінат повного циклу, який уключає коксохімічне, гірничодобувне й металургійне виробництва. Висока ефективність його діяльності забезпечено комплексним переробленням сировини: амоніак, який міститься в коксовому газі, використовують для виробництва азотних добрив, сірководень – для виготовлення технічної сульфатної кислоти. Це дає змогу мінімізувати втрати й знизити собівартість кінцевої продукції.
Правильна відповідь: Б.','[]','https://zno.osvita.ua/geography/690/','https://lv.testportal.gov.ua/wp-content/arhiv/2025/2025_geo-2.pdf','© Український центр оцінювання якості освіти, НМТ-2025; джерело наведено в записі.','44ce2f03fdc416958bac6df6883d0d62d9ab5816d71fe741f41eea83f8d47002','1','official','single_choice',(SELECT id FROM topics WHERE subject_slug='geography' AND name='Металургія')) ON CONFLICT(id) DO UPDATE SET topic_id=excluded.topic_id,canonical_key=excluded.canonical_key,active=excluded.active,source_kind=excluded.source_kind,exam_format=excluded.exam_format;
